  ('00000000-0000-4000-8003-000000000031', '00000000-0000-4000-8002-000000000022', '00000000-0000-4000-8001-000000000049', 'spectrophotometrie', 'Spectrophotométrie UV-visible', 'UV-visible spectrophotometry', 1),
  ('00000000-0000-4000-8003-000000000032', '00000000-0000-4000-8002-000000000023', '00000000-0000-4000-8001-000000000051', 'paroi-bacterienne', 'Paroi bactérienne et coloration de Gram', 'Bacterial cell wall and Gram stain', 1);
insert into public.qcms (id, course_id, module_id, type, stem, explanation, difficulty, source, exam_year, tags, status) values
  ('00000000-0000-4000-8004-000000000001', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'multiple', 'Concernant la scapula (omoplate) :', 'La scapula est un os plat triangulaire de la ceinture scapulaire. Sa face postérieure porte l’épine, qui se prolonge latéralement par l’acromion (articulé avec la clavicule). La cavité glénoïdale reçoit la tête humérale.', 2, null, null, array['ostéologie', 'membre supérieur'], 'published'),
  ('00000000-0000-4000-8004-000000000002', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'single', 'Quel os du carpe s’articule avec le radius et est le plus fréquemment fracturé ?', 'Le scaphoïde (rangée proximale) s’articule avec le radius. Sa fracture, typique d’une chute sur la paume de la main, poignet en extension, expose au risque de nécrose du pôle proximal.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000003', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'multiple', 'Concernant l’humérus :', 'Deux rapports nerveux à connaître : nerf radial (sillon postérieur de la diaphyse, exposé dans les fractures diaphysaires) et nerf ulnaire (derrière l’épicondyle médial). Le col chirurgical, sous les tubercules, est le siège fréquent des fractures du sujet âgé.', 3, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000004', '00000000-0000-4000-8003-000000000002', '00000000-0000-4000-8001-000000000002', 'multiple', 'Concernant le glucose :', 'Le D-glucose est un aldohexose (C6H12O6). En solution aqueuse, la forme linéaire est minoritaire : la cyclisation hémiacétalique donne surtout le β-D-glucopyranose.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000005', '00000000-0000-4000-8003-000000000003', '00000000-0000-4000-8001-000000000002', 'single', 'Quel acide aminé ne possède pas de carbone asymétrique ?', 'La chaîne latérale de la glycine est un atome d’hydrogène : son carbone α porte deux H, il n’est donc pas chiral.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000006', '00000000-0000-4000-8003-000000000003', '00000000-0000-4000-8001-000000000002', 'multiple', 'La liaison peptidique :', 'Condensation entre COOH α et NH2 α avec départ d’eau. La délocalisation électronique donne à la liaison C–N un caractère partiel de double liaison : le groupement peptidique est plan, sans rotation libre.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000007', '00000000-0000-4000-8003-000000000007', '00000000-0000-4000-8001-000000000006', 'multiple', 'Concernant la membrane plasmique :', 'Bicouche de phospholipides amphiphiles dans laquelle diffusent protéines et cholestérol (mosaïque fluide). L’asymétrie membranaire place les glycolipides et glycoprotéines sur la face externe.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000008', '00000000-0000-4000-8003-000000000008', '00000000-0000-4000-8001-000000000006', 'single', 'Quel organite est le siège de la phosphorylation oxydative ?', 'La chaîne respiratoire et l’ATP synthase sont localisées dans la membrane interne mitochondriale (crêtes).', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000009', '00000000-0000-4000-8003-000000000009', '00000000-0000-4000-8001-000000000006', 'multiple', 'Au cours de la mitose :', 'Prophase → prométaphase → métaphase → anaphase → télophase. La mitose conserve la ploïdie ; la réduction chromosomique est le fait de la méiose.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000010', '00000000-0000-4000-8003-000000000012', '00000000-0000-4000-8001-000000000009', 'multiple', 'Le potentiel de repos d’un neurone :', 'Au repos, la membrane est surtout perméable au K+ : le potentiel de repos est proche du potentiel d’équilibre du potassium. La pompe Na+/K+ (électrogène) maintient les gradients.', 3, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000011', '00000000-0000-4000-8003-000000000013', '00000000-0000-4000-8001-000000000009', 'single', 'Quelle hormone est hypoglycémiante ?', 'L’insuline (cellules β des îlots de Langerhans) est la seule hormone hypoglycémiante ; les autres citées sont hyperglycémiantes.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000012', '00000000-0000-4000-8003-000000000004', '00000000-0000-4000-8001-000000000003', 'single', 'L’unité de pression du Système international est :', '1 Pa = 1 N·m⁻². Le mmHg et le cmH2O restent utilisés en médecine mais ne sont pas des unités SI.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000013', '00000000-0000-4000-8003-000000000005', '00000000-0000-4000-8001-000000000003', 'multiple', 'Concernant l’osmolarité et les solutions :', 'L’osmolarité est une propriété colligative : elle dépend du nombre de particules en solution. L’eau se déplace vers le compartiment le plus concentré en osmoles efficaces.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000014', '00000000-0000-4000-8003-000000000010', '00000000-0000-4000-8001-000000000007', 'multiple', 'Concernant la fécondation humaine :', 'L’ovocyte est bloqué en métaphase II jusqu’à la fécondation. La réaction corticale modifie la zone pellucide et bloque la polyspermie.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000015', '00000000-0000-4000-8003-000000000011', '00000000-0000-4000-8001-000000000008', 'single', 'L’épiderme est un épithélium :', 'Épithélium malpighien kératinisé : couches basale, épineuse, granuleuse et cornée.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000016', '00000000-0000-4000-8003-000000000006', '00000000-0000-4000-8001-000000000004', 'single', 'Pour une variable suivant une loi normale, l’intervalle moyenne ± 1,96 écart-type contient environ :', 'μ ± 1σ ≈ 68 %, μ ± 1,96σ ≈ 95 %, μ ± 2,58σ ≈ 99 %, μ ± 3σ ≈ 99,7 %.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000017', '00000000-0000-4000-8003-000000000014', '00000000-0000-4000-8001-000000000011', 'multiple', 'Concernant le cœur :', 'Le ventricule gauche, qui éjecte dans la circulation systémique à haute pression, a la paroi la plus épaisse. Le nœud sinusal, près de l’abouchement de la veine cave supérieure, est le pacemaker physiologique.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000018', '00000000-0000-4000-8003-000000000015', '00000000-0000-4000-8001-000000000011', 'single', 'Le débit cardiaque est égal à :', 'Qc = FC × VES (≈ 70 × 70 mL ≈ 5 L/min au repos). À noter : PAM = Qc × RVS.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000019', '00000000-0000-4000-8003-000000000016', '00000000-0000-4000-8001-000000000011', 'multiple', 'Le surfactant pulmonaire :', 'Mélange de phospholipides (surtout dipalmitoylphosphatidylcholine) et de protéines, il stabilise les alvéoles et prévient leur collapsus en fin d’expiration.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000020', '00000000-0000-4000-8003-000000000017', '00000000-0000-4000-8001-000000000012', 'single', 'La sécrétion d’acide chlorhydrique gastrique est assurée par les :', 'Les cellules pariétales sécrètent HCl (pompe H+/K+-ATPase) et le facteur intrinsèque. Les cellules principales sécrètent le pepsinogène, les cellules G la gastrine.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000021', '00000000-0000-4000-8003-000000000018', '00000000-0000-4000-8001-000000000016', 'multiple', 'Concernant les immunoglobulines :', 'Retenir : IgG (placenta, majoritaires), IgM (pentamère, réponse primaire), IgA (muqueuses, dimère sécrétoire), IgE (allergie, parasites), IgD (récepteur du lymphocyte B naïf).', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000022', '00000000-0000-4000-8003-000000000019', '00000000-0000-4000-8001-000000000017', 'single', 'Le caryotype humain normal comporte :', '46 chromosomes : 22 paires d’autosomes + 1 paire de gonosomes (46,XX ou 46,XY).', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000023', '00000000-0000-4000-8003-000000000020', '00000000-0000-4000-8001-000000000020', 'single', 'La denture permanente complète comporte :', 'Par hémi-arcade : 2 incisives, 1 canine, 2 prémolaires, 3 molaires = 8, soit 32 dents (dents de sagesse comprises).', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000024', '00000000-0000-4000-8003-000000000021', '00000000-0000-4000-8001-000000000020', 'multiple', 'Concernant l’émail dentaire :', 'Émail ≈ 96 % de minéral (hydroxyapatite). Il dérive de l’organe de l’émail (ectoderme) ; la dentine et la pulpe dérivent de l’ectomésenchyme.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000025', '00000000-0000-4000-8003-000000000020', '00000000-0000-4000-8001-000000000020', 'single', 'La denture temporaire (lactéale) comporte :', 'Par hémi-arcade : 2 incisives, 1 canine, 2 molaires temporaires = 5, soit 20 dents. Il n’y a pas de prémolaires temporaires.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000026', '00000000-0000-4000-8003-000000000022', '00000000-0000-4000-8001-000000000024', 'single', 'La synthèse des protéines destinées à être sécrétées débute sur les ribosomes et se poursuit dans :', 'Voie de sécrétion : ribosomes liés au REG → appareil de Golgi → vésicules de sécrétion → exocytose.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000027', '00000000-0000-4000-8003-000000000025', '00000000-0000-4000-8001-000000000031', 'multiple', 'Concernant la dentine :', 'La dentine (≈ 70 % minéral) forme la masse de la dent ; les prolongements odontoblastiques occupent les tubules, ce qui explique la sensibilité dentinaire.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000028', '00000000-0000-4000-8003-000000000023', '00000000-0000-4000-8001-000000000030', 'single', 'Parmi ces muscles, lequel est élévateur de la mandibule ?', 'Élévateurs : masséter, temporal, ptérygoïdien médial. Le ptérygoïdien latéral est propulseur ; les sus-hyoïdiens (digastrique, mylo- et génio-hyoïdien) sont abaisseurs.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000029', '00000000-0000-4000-8003-000000000024', '00000000-0000-4000-8001-000000000030', 'single', 'La sensibilité des dents mandibulaires est assurée par le nerf :', 'Branche du nerf mandibulaire (V3), le nerf alvéolaire inférieur chemine dans le canal mandibulaire ; c’est la cible de l’anesthésie tronculaire à l’épine de Spix.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000030', '00000000-0000-4000-8003-000000000026', '00000000-0000-4000-8001-000000000039', 'single', 'Le numéro atomique Z d’un élément représente :', 'Z = nombre de protons (égal au nombre d’électrons de l’atome neutre). A = nombre de nucléons = Z + N.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000031', '00000000-0000-4000-8003-000000000027', '00000000-0000-4000-8001-000000000039', 'multiple', 'Concernant le pH :', 'L’échelle de pH est logarithmique : une unité de pH correspond à un facteur 10 de [H3O+]. Le pH artériel normal est de 7,38–7,42.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000032', '00000000-0000-4000-8003-000000000029', '00000000-0000-4000-8001-000000000044', 'multiple', 'La cellule végétale :', 'Trois particularités de la cellule végétale : paroi, plastes, grande vacuole. Elle conserve toutefois des mitochondries.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000033', '00000000-0000-4000-8003-000000000028', '00000000-0000-4000-8001-000000000040', 'single', 'Un atome de carbone hybridé sp3 présente une géométrie :', 'sp3 : 4 orbitales hybrides à 109,5° (tétraèdre, ex. méthane). sp2 : plan trigonal à 120°. sp : linéaire à 180°.', 1, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000034', '00000000-0000-4000-8003-000000000030', '00000000-0000-4000-8001-000000000048', 'single', 'Dans le modèle de Michaelis-Menten, la constante Km correspond à :', 'Km s’exprime en concentration ; plus Km est faible, plus l’affinité apparente de l’enzyme pour son substrat est grande.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000035', '00000000-0000-4000-8003-000000000032', '00000000-0000-4000-8001-000000000051', 'multiple', 'Concernant les bactéries à Gram positif :', 'Le peptidoglycane épais retient le complexe violet de gentiane–lugol malgré la décoloration à l’alcool : les Gram positif restent violets, les Gram négatif sont recolorés en rose par la fuchsine.', 2, null, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000036', '00000000-0000-4000-8003-000000000031', '00000000-0000-4000-8001-000000000049', 'single', 'Selon la loi de Beer-Lambert, l’absorbance A s’écrit :', 'A = log(I0/I) = ε·l·c, avec ε le coefficient d’absorption molaire, l le trajet optique et c la concentration. Relation linéaire valable pour les solutions diluées.', 1, null, null, '{}', 'published'),
  ('cc053e53-231c-593f-9d0c-ef1d1ad26753', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Parmi les propositions suivantes relatives à la méiose, laquelle (lesquelles) est (sont) exacte (s) :', 'Avant la méiose, la cellule germinale (spermatocyte I, ovocyte I) réplique son ADN en phase S : elle entre en méiose avec 2n chromosomes bichromatidiens et 4C d''ADN. La première division sépare les homologues (réductionnelle), la seconde sépare les chromatides (équationnelle). (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'L’anaphase II correspond :', 'En anaphase II, les centromères se clivent et les chromatides sœurs de chaque chromosome migrent vers des pôles opposés, comme dans une mitose. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('18dc64a7-0d50-5410-b1d0-671990aaa7bf', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'La méiose :', 'La méiose est propre aux cellules germinales et constitue la phase de maturation de la gamétogenèse. Chez la femme, elle est bloquée deux fois : en prophase I (diplotène) jusqu''à la puberté, puis en métaphase II jusqu''à la fécondation. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('13c4b2ad-21d0-5c9e-9b69-19afafba5abf', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Concernant la méiose :', 'La prophase I est la phase la plus longue de la méiose (appariement des homologues, crossing-over) et elle suit la réplication de l''ADN. L''ordre des divisions est : réductionnelle puis équationnelle. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'la méiose se déroule à la phase de:', 'La gamétogenèse comprend : la multiplication (mitoses des gonies), l''accroissement (gonie → cyte I), la maturation (méiose) et, chez l''homme, la différenciation (spermiogenèse). (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Le phénomène de crossing-over est réalisé au stade de :', 'La prophase I comprend le leptotène, le zygotène (appariement des homologues), le pachytène (crossing-over), le diplotène (chiasmas visibles, blocage de l''ovocyte) et la diacinèse. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Il permet (le crossing-over) :', 'Le crossing-over échange des segments entre chromatides non sœurs de chromosomes homologues : il crée de nouvelles combinaisons d''allèles, source de diversité génétique. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'La gamétogenèse comporte toutes ces phases sauf une :', 'Les phases de la gamétogenèse sont la multiplication (ou prolifération), l''accroissement, la maturation et, chez l''homme, la différenciation. La « division cellulaire » n''est pas une phase : c''est un mécanisme présent dans plusieurs phases. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('8bdea8b0-ce2e-5289-bc94-fbdc47c4a301', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Durant quel stade se réalise le crossing over', 'Le crossing-over se produit au pachytène de la prophase I, lorsque les chromosomes homologues sont complètement appariés (bivalents). (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('504972c4-f00c-57db-bbb0-189e0f59b65d', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'L’anaphase I de la méiose :', 'En anaphase I, les homologues se séparent : chaque chromosome, encore formé de deux chromatides, migre vers un pôle. La réduction du nombre de chromosomes et de la quantité d''ADN par cellule n''est effective qu''après la cytodiérèse (fin de la division I). (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'dans le stade de l’anaphase II de la méiose on a :', 'En anaphase II, les centromères se clivent : chaque chromosome se « dédouble » en deux chromatides qui migrent vers des pôles opposés. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('fa5f508c-2385-5144-8579-ff46c3b43388', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'quelle est celle qui se rapporte aux spermatocytes au stade de la métaphase II de méiose :', '[À revoir avant publication — clé douteuse.] Aucune proposition n''est exacte telle qu''imprimée : le spermatocyte II en métaphase II a n chromosomes, 2n chromatides et 2n ADN. La proposition D retenue par le corrigé type contient probablement une faute de frappe (« 4n » au lieu de « n »). Le spermatocyte II est haploïde : il a n chromosomes, chacun encore formé de deux chromatides, soit 2n chromatides et 2n (2C) d''ADN en métaphase II.', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia', 'a-revoir:cle-douteuse'], 'draft'),
  ('1394f17f-77e1-569d-9cd9-2163801f655d', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Parmi les cellules Suivantes lesquelles sont haploïdes :', 'Après la première division méiotique, les cellules sont haploïdes : spermatocytes II, ovocytes II, spermatides, spermatozoïdes. Les gonies et les cytes I sont diploïdes. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'la méiose :', 'La méiose ne concerne que les cellules germinales engagées (cytes I). Par la répartition aléatoire des homologues et les crossing-over, elle produit des gamètes haploïdes génétiquement tous différents. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'toutes ces cellules sont diploïdes sauf une :', '[À revoir avant publication — clé ambiguë.] Clé d’origine : « A ou C ». Source : p. 5, question 15.', null, 'UMMTO', null, array['import:ummto-2023-24', 'a-revoir:ambiguous_key'], 'draft'),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'la méiose :', 'En divisant par deux le nombre de chromosomes, la méiose permet à la fécondation de restituer exactement 2n : l''alternance méiose–fécondation maintient le caryotype de l''espèce d''une génération à l''autre. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'toutes ces cellules sont diploïdes sauf une :', 'Seules les cellules issues de la première division méiotique sont haploïdes. Les spermatocytes II le sont ; les gonies, les cytes I et les cellules somatiques (Leydig) sont diploïdes. (Explication rédigée par IA : signalez la question si vous repérez une erreur.)', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia'], 'published'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'la méiose se déroule à la phase de :', '[À revoir avant publication — clé douteuse.] Le corrigé type retient B (différenciation), alors que la méiose correspond à la phase de maturation (A), comme l''indique la question identique du même cours. La gamétogenèse comprend la multiplication, l''accroissement, la maturation (méiose) et, chez l''homme, la différenciation (spermiogenèse).', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia', 'a-revoir:cle-douteuse'], 'draft'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', '00000000-0000-4000-8003-000000000039', '00000000-0000-4000-8001-000000000007', 'multiple', 'Dans le stade de l’anaphase II de la méiose on a :', '[À revoir avant publication — clé douteuse.] Le corrigé type retient B et D, mais la séparation des homologues (D) a lieu en anaphase I ; en anaphase II, B et C sont justes (voir la question identique du même cours). En anaphase II, les centromères se clivent et les chromatides sœurs se séparent vers des pôles opposés.', null, 'UMMTO', null, array['import:ummto-2023-24', 'explication:ia', 'a-revoir:cle-douteuse'], 'draft'),
  ('71862bed-070f-5364-af8c-98b1e3e39551', '00000000-0000-4000-8003-000000000040', '00000000-0000-4000-8001-000000000007', 'multiple', 'Parmi les propositions suivantes relatives aux spermatogonies, laquelle (lesquelles) est (sont) exacte (s) :', null, null, 'UMMTO', null, array['import:ummto-2023-24'], 'published'),
