insert into public.qcm_options (qcm_id, label, body, is_correct, explanation) values
  ('00000000-0000-4000-8004-000000000001', 'A', 'C’est un os plat de forme triangulaire', true, null),
  ('00000000-0000-4000-8004-000000000001', 'B', 'Elle s’articule avec la clavicule par l’acromion', true, 'Articulation acromio-claviculaire.'),
  ('00000000-0000-4000-8004-000000000001', 'C', 'Sa cavité glénoïdale s’articule avec la tête de l’humérus', true, null),
  ('00000000-0000-4000-8004-000000000001', 'D', 'Elle présente une épine sur sa face antérieure', false, 'L’épine de la scapula est sur la face postérieure.'),
  ('00000000-0000-4000-8004-000000000001', 'E', 'Le processus coracoïde naît de son bord médial', false, 'Il naît du bord supérieur, près du col de la scapula.'),
  ('00000000-0000-4000-8004-000000000002', 'A', 'Le lunatum', false, null),
  ('00000000-0000-4000-8004-000000000002', 'B', 'Le scaphoïde', true, null),
  ('00000000-0000-4000-8004-000000000002', 'C', 'Le pisiforme', false, null),
  ('00000000-0000-4000-8004-000000000002', 'D', 'L’hamatum', false, null),
  ('00000000-0000-4000-8004-000000000002', 'E', 'Le trapèze', false, null),
  ('00000000-0000-4000-8004-000000000003', 'A', 'Le nerf radial chemine dans le sillon du nerf radial, à la face postérieure de la diaphyse', true, null),
  ('00000000-0000-4000-8004-000000000003', 'B', 'Le nerf ulnaire passe en arrière de l’épicondyle médial', true, null),
  ('00000000-0000-4000-8004-000000000003', 'C', 'Le col chirurgical est situé au-dessus des tubercules majeur et mineur', false, 'Il est situé sous les tubercules ; le col anatomique borde la tête.'),
  ('00000000-0000-4000-8004-000000000003', 'D', 'Le tubercule majeur est situé en dedans du tubercule mineur', false, 'Le tubercule majeur est latéral.'),
  ('00000000-0000-4000-8004-000000000003', 'E', 'La trochlée humérale s’articule avec l’incisure trochléaire de l’ulna', true, null),
  ('00000000-0000-4000-8004-000000000004', 'A', 'C’est un aldohexose', true, null),
  ('00000000-0000-4000-8004-000000000004', 'B', 'Sa formule brute est C6H12O6', true, null),
  ('00000000-0000-4000-8004-000000000004', 'C', 'C’est un cétose', false, 'Le fructose est un cétose ; le glucose porte une fonction aldéhyde.'),
  ('00000000-0000-4000-8004-000000000004', 'D', 'En solution, il existe majoritairement sous forme cyclique', true, 'Principalement sous forme pyranose (β > α).'),
  ('00000000-0000-4000-8004-000000000004', 'E', 'Le saccharose est formé de deux molécules de glucose', false, 'Saccharose = glucose + fructose ; le maltose = glucose + glucose.'),
  ('00000000-0000-4000-8004-000000000005', 'A', 'Alanine', false, null),
  ('00000000-0000-4000-8004-000000000005', 'B', 'Glycine', true, null),
  ('00000000-0000-4000-8004-000000000005', 'C', 'Sérine', false, null),
  ('00000000-0000-4000-8004-000000000005', 'D', 'Valine', false, null),
  ('00000000-0000-4000-8004-000000000005', 'E', 'Leucine', false, null),
  ('00000000-0000-4000-8004-000000000006', 'A', 'S’établit entre le carboxyle α d’un acide aminé et l’amine α du suivant', true, null),
  ('00000000-0000-4000-8004-000000000006', 'B', 'Libère une molécule d’eau lors de sa formation', true, null),
  ('00000000-0000-4000-8004-000000000006', 'C', 'Présente un caractère partiel de double liaison', true, null),
  ('00000000-0000-4000-8004-000000000006', 'D', 'Permet une libre rotation autour de la liaison C–N', false, 'La mésomérie rend la liaison C–N plane et rigide.'),
  ('00000000-0000-4000-8004-000000000006', 'E', 'Peut être rompue par hydrolyse', true, null),
  ('00000000-0000-4000-8004-000000000007', 'A', 'Son organisation est décrite par le modèle de la mosaïque fluide (Singer et Nicolson)', true, null),
  ('00000000-0000-4000-8004-000000000007', 'B', 'Les phospholipides sont des molécules amphiphiles', true, null),
  ('00000000-0000-4000-8004-000000000007', 'C', 'Le cholestérol module sa fluidité', true, null),
  ('00000000-0000-4000-8004-000000000007', 'D', 'Les glucides membranaires sont situés sur la face cytosolique', false, 'Ils forment le glycocalyx, sur la face extracellulaire.'),
  ('00000000-0000-4000-8004-000000000007', 'E', 'Les protéines intrinsèques traversent toujours toute la bicouche', false, 'Certaines sont seulement ancrées dans un feuillet.'),
  ('00000000-0000-4000-8004-000000000008', 'A', 'Réticulum endoplasmique granuleux', false, null),
  ('00000000-0000-4000-8004-000000000008', 'B', 'Appareil de Golgi', false, null),
  ('00000000-0000-4000-8004-000000000008', 'C', 'Mitochondrie', true, null),
  ('00000000-0000-4000-8004-000000000008', 'D', 'Lysosome', false, null),
  ('00000000-0000-4000-8004-000000000008', 'E', 'Peroxysome', false, null),
  ('00000000-0000-4000-8004-000000000009', 'A', 'La prophase est marquée par la condensation des chromosomes', true, null),
  ('00000000-0000-4000-8004-000000000009', 'B', 'En métaphase, les chromosomes s’alignent sur la plaque équatoriale', true, null),
  ('00000000-0000-4000-8004-000000000009', 'C', 'L’anaphase correspond à la séparation des chromatides sœurs', true, null),
  ('00000000-0000-4000-8004-000000000009', 'D', 'Des crossing-over se produisent en prophase', false, 'Les crossing-over sont propres à la prophase I de méiose.'),
  ('00000000-0000-4000-8004-000000000009', 'E', 'Elle aboutit à deux cellules filles haploïdes', false, 'La mitose donne deux cellules diploïdes identiques.'),
  ('00000000-0000-4000-8004-000000000010', 'A', 'Est d’environ −70 mV', true, null),
  ('00000000-0000-4000-8004-000000000010', 'B', 'Dépend principalement de la perméabilité membranaire au K+', true, null),
  ('00000000-0000-4000-8004-000000000010', 'C', 'Est entretenu par la pompe Na+/K+-ATPase, qui fait sortir 3 Na+ et entrer 2 K+', true, null),
  ('00000000-0000-4000-8004-000000000010', 'D', 'Correspond à un intérieur cellulaire positif par rapport à l’extérieur', false, null),
  ('00000000-0000-4000-8004-000000000010', 'E', 'Est aboli par la tétrodotoxine', false, 'La TTX bloque les canaux Na+ voltage-dépendants : elle abolit le potentiel d’action, pas le potentiel de repos.'),
  ('00000000-0000-4000-8004-000000000011', 'A', 'Glucagon', false, null),
