  ('00000000-0000-4000-8004-000000000028', 'E', 'Platysma', false, null),
  ('00000000-0000-4000-8004-000000000029', 'A', 'Alvéolaire inférieur', true, null),
  ('00000000-0000-4000-8004-000000000029', 'B', 'Facial', false, null),
  ('00000000-0000-4000-8004-000000000029', 'C', 'Lingual', false, null),
  ('00000000-0000-4000-8004-000000000029', 'D', 'Hypoglosse', false, null),
  ('00000000-0000-4000-8004-000000000029', 'E', 'Glosso-pharyngien', false, null),
