  ('00000000-0000-4000-8004-000000000030', 'B', 'Le nombre de protons', true, null),
  ('00000000-0000-4000-8004-000000000030', 'C', 'Le nombre de nucléons', false, null),
  ('00000000-0000-4000-8004-000000000030', 'D', 'La masse atomique', false, null),
  ('00000000-0000-4000-8004-000000000030', 'E', 'Le nombre d’électrons de valence', false, null),
  ('00000000-0000-4000-8004-000000000031', 'A', 'pH = −log [H3O+]', true, null),
  ('00000000-0000-4000-8004-000000000031', 'B', 'Une solution neutre à 25 °C a un pH de 7', true, null),
  ('00000000-0000-4000-8004-000000000031', 'C', 'Une solution de pH 3 est dix fois plus acide qu’une solution de pH 4', true, null),
  ('00000000-0000-4000-8004-000000000031', 'D', 'Une solution diluée de base forte a un pH inférieur à 7', false, null),
  ('00000000-0000-4000-8004-000000000031', 'E', 'Le pH plasmatique normal est d’environ 7,40', true, null),
  ('00000000-0000-4000-8004-000000000032', 'A', 'Possède une paroi pectocellulosique', true, null),
  ('00000000-0000-4000-8004-000000000032', 'B', 'Contient des plastes, dont les chloroplastes', true, null),
  ('00000000-0000-4000-8004-000000000032', 'C', 'Possède généralement une vacuole volumineuse', true, null),
  ('00000000-0000-4000-8004-000000000032', 'D', 'Est dépourvue de mitochondries', false, 'Elle possède des mitochondries en plus des chloroplastes.'),
  ('00000000-0000-4000-8004-000000000032', 'E', 'Possède des centrioles typiques', false, 'Les végétaux supérieurs n’ont pas de centrioles.'),
  ('00000000-0000-4000-8004-000000000033', 'A', 'Linéaire', false, null),
  ('00000000-0000-4000-8004-000000000033', 'B', 'Plane trigonale', false, null),
  ('00000000-0000-4000-8004-000000000033', 'C', 'Tétraédrique', true, null),
  ('00000000-0000-4000-8004-000000000033', 'D', 'Octaédrique', false, null),
  ('00000000-0000-4000-8004-000000000033', 'E', 'Pyramidale à base carrée', false, null),
  ('00000000-0000-4000-8004-000000000034', 'A', 'La vitesse maximale de la réaction', false, null),
  ('00000000-0000-4000-8004-000000000034', 'B', 'La concentration en substrat pour laquelle v = Vmax/2', true, null),
  ('00000000-0000-4000-8004-000000000034', 'C', 'La concentration totale en enzyme', false, null),
  ('00000000-0000-4000-8004-000000000034', 'D', 'La vitesse initiale de la réaction', false, null),
  ('00000000-0000-4000-8004-000000000034', 'E', 'La constante d’équilibre de la réaction', false, null),
  ('00000000-0000-4000-8004-000000000035', 'A', 'Leur paroi contient une épaisse couche de peptidoglycane', true, null),
  ('00000000-0000-4000-8004-000000000035', 'B', 'Elles apparaissent violettes après coloration de Gram', true, null),
  ('00000000-0000-4000-8004-000000000035', 'C', 'Elles possèdent une membrane externe riche en lipopolysaccharide', false, 'La membrane externe à LPS caractérise les Gram négatif.'),
  ('00000000-0000-4000-8004-000000000035', 'D', 'Staphylococcus aureus est un cocci à Gram positif', true, null),
  ('00000000-0000-4000-8004-000000000035', 'E', 'Escherichia coli est un bacille à Gram positif', false, 'E. coli est un bacille à Gram négatif.'),
  ('00000000-0000-4000-8004-000000000036', 'A', 'A = ε · l · c', true, null),
  ('00000000-0000-4000-8004-000000000036', 'B', 'A = ε / (l · c)', false, null),
  ('00000000-0000-4000-8004-000000000036', 'C', 'A = l / c', false, null),
  ('00000000-0000-4000-8004-000000000036', 'D', 'A = log(I / I0) · c', false, null),
  ('00000000-0000-4000-8004-000000000036', 'E', 'A = ε · c / l', false, null),
  ('cc053e53-231c-593f-9d0c-ef1d1ad26753', 'A', 'La méiose est précédée d’une phase de réplication d’ADN', true, 'Vrai : une seule réplication (phase S) précède les deux divisions méiotiques.'),
  ('cc053e53-231c-593f-9d0c-ef1d1ad26753', 'B', 'Toutes les cellules de l’organisme subissent une méiose', false, 'Faux : seules les cellules germinales font une méiose ; les cellules somatiques se divisent par mitose.'),
  ('cc053e53-231c-593f-9d0c-ef1d1ad26753', 'C', 'La première mitose de la méiose est réductionnelle', true, 'Vrai : la première division sépare les chromosomes homologues et fait passer de 2n à n chromosomes.'),
  ('cc053e53-231c-593f-9d0c-ef1d1ad26753', 'D', 'Les cellules qui sont prêtes à rentrer en méiose possèdent un noyau contenant 2n ch et 2n ADN', false, 'Faux : après la réplication, le noyau contient 2n chromosomes mais 4n (4C) d''ADN.'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', 'A', 'à la migration des chromosomes homologue', false, 'Faux : la migration des chromosomes homologues caractérise l''anaphase I.'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', 'B', 'au dédoublement des centromères', true, 'Vrai : le clivage (dédoublement) des centromères libère les chromatides sœurs.'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', 'C', 'à la disjonction des chromosomes bivalents', false, 'Faux : les bivalents (tétrades) se séparent en anaphase I.'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', 'D', 'à la séparation des chromatides sœurs', true, 'Vrai : les chromatides sœurs se séparent et deviennent des chromosomes monochromatidiens.'),
  ('962e6597-e90b-56fd-82fa-cd4f42db1436', 'E', 'à la disjonction des chromosomes homologues', false, 'Faux : la disjonction des homologues a lieu en anaphase I.'),
  ('18dc64a7-0d50-5410-b1d0-671990aaa7bf', 'A', 'Concerne souvent les cellules germinales.', false, 'Faux : la méiose concerne toujours, et uniquement, les cellules germinales ; « souvent » rend la proposition fausse.'),
  ('18dc64a7-0d50-5410-b1d0-671990aaa7bf', 'B', 'Est un processus secondaire dans la gamétogenèse', false, 'Faux : c''est une étape essentielle de la gamétogenèse (phase de maturation).'),
  ('18dc64a7-0d50-5410-b1d0-671990aaa7bf', 'C', 'Chez la femme peut être bloquée en métaphase 1', false, 'Faux : l''ovocyte est bloqué en prophase I puis en métaphase II, jamais en métaphase I.'),
  ('18dc64a7-0d50-5410-b1d0-671990aaa7bf', 'D', 'Permet aux ovogonies de devenir haploïdes', true, 'Vrai : la lignée issue des ovogonies (diploïdes) devient haploïde grâce à la méiose.'),
  ('13c4b2ad-21d0-5c9e-9b69-19afafba5abf', 'A', 'Permet des échanges des chromatides responsable de variabilité de l''espèce humaine', false, 'Considérée fausse par le corrigé type : le crossing-over échange des segments entre chromatides non sœurs de chromosomes homologues ; la formulation « échanges des chromatides » est jugée imprécise.'),
  ('13c4b2ad-21d0-5c9e-9b69-19afafba5abf', 'B', 'Comprend deux divisions, une équationnelle puis réductionnelle', false, 'Faux : c''est l''inverse, la première division est réductionnelle et la seconde équationnelle.'),
  ('13c4b2ad-21d0-5c9e-9b69-19afafba5abf', 'C', 'La cellule germinale souche donne toujours 4 gamètes matures haploïdes', false, 'Faux : chez la femme, un ovocyte I ne donne qu''un seul ovule (plus les globules polaires).'),
  ('13c4b2ad-21d0-5c9e-9b69-19afafba5abf', 'D', 'La prophase 1 est la phase la plus longue précédée par la réplication d''ADN', true, 'Vrai : la prophase I est la plus longue (des années chez la femme) et elle est précédée de la réplication de l''ADN.'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', 'A', 'différentiation', false, 'Faux : la différenciation (spermiogenèse) suit la méiose et transforme les spermatides en spermatozoïdes.'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', 'B', 'maturation', true, 'Vrai : la méiose correspond à la phase de maturation.'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', 'C', 'accroissement', false, 'Faux : l''accroissement précède la méiose (spermatogonie → spermatocyte I, ovogonie → ovocyte I).'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', 'D', 'multiplication', false, 'Faux : la multiplication se fait par mitoses des gonies.'),
  ('ffe570ce-d624-5329-8a82-4c53b6324e5f', 'E', 'prolifération', false, 'Faux : la prolifération est un autre nom de la multiplication (mitoses).'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', 'A', 'pachytène', true, 'Vrai : les crossing-over se produisent au pachytène, quand les homologues sont complètement appariés.'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', 'B', 'Zygotène', false, 'Faux : au zygotène, les homologues s''apparient (formation du complexe synaptonémal).'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', 'C', 'leptotène', false, 'Faux : au leptotène, les chromosomes commencent seulement à se condenser.'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', 'D', 'diplotène', false, 'Faux : au diplotène, on voit les chiasmas, traces des crossing-over déjà réalisés.'),
  ('6c3abe0c-24fc-57af-857f-afb3f91811a2', 'E', 'Diacinèse', false, 'Faux : la diacinèse termine la prophase I (condensation maximale).'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', 'A', 'La restauration de la diploïdie', false, 'Faux : la diploïdie est restaurée par la fécondation.'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', 'B', 'La variabilité de l’espèce', true, 'Vrai : il réalise un brassage intrachromosomique qui augmente la variabilité.'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', 'C', 'l''obtention de l''haploïdie', false, 'Faux : l''haploïdie résulte de la séparation des homologues en anaphase I.'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', 'D', 'La détermination du sexe', false, 'Faux : le sexe est déterminé à la fécondation par le chromosome X ou Y du spermatozoïde.'),
  ('4c242cfe-8c0b-51af-a537-14f9f2cc8f28', 'E', 'La stabilité du stock chromosomique', false, 'Faux : il ne change pas le nombre de chromosomes ; la stabilité du stock est assurée par l''alternance méiose–fécondation.'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', 'A', 'prolifération', false, 'Faux : la prolifération (multiplication des gonies) est bien une phase.'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', 'B', 'multiplication', false, 'Faux : la multiplication est une phase.'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', 'C', 'division cellulaire', true, 'Vrai, c''est l''intrus : la division cellulaire n''est pas une phase de la gamétogenèse.'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', 'D', 'accroissement', false, 'Faux : l''accroissement est une phase.'),
  ('5498c0ab-47c0-599c-af23-d935898438a9', 'E', 'maturation', false, 'Faux : la maturation (méiose) est une phase.'),
  ('8bdea8b0-ce2e-5289-bc94-fbdc47c4a301', 'A', 'Zygotène', false, 'Faux : le zygotène correspond à l''appariement des homologues.'),
  ('8bdea8b0-ce2e-5289-bc94-fbdc47c4a301', 'B', 'Pachytène', true, 'Vrai : le pachytène est le stade des crossing-over.'),
  ('8bdea8b0-ce2e-5289-bc94-fbdc47c4a301', 'C', 'Diacinèse', false, 'Faux : la diacinèse termine la prophase I.'),
  ('8bdea8b0-ce2e-5289-bc94-fbdc47c4a301', 'D', 'Diplotène', false, 'Faux : au diplotène, les chiasmas deviennent visibles, mais les échanges ont déjà eu lieu.'),
  ('504972c4-f00c-57db-bbb0-189e0f59b65d', 'A', 'Permet la division de moitié que la quantité d’ADN', false, 'Considérée fausse : l''anaphase n''est qu''une migration ; la quantité d''ADN par cellule n''est divisée par deux qu''à la fin de la division I.'),
  ('504972c4-f00c-57db-bbb0-189e0f59b65d', 'B', 'Permet la division de moitié que la quantité de chromosomes', false, 'Considérée fausse pour la même raison : le passage de 2n à n chromosomes par cellule est effectif à la fin de la division I, pas pendant l''anaphase.'),
  ('504972c4-f00c-57db-bbb0-189e0f59b65d', 'C', 'Correspond à la migration des chromosomes bichromatidiens', true, 'Vrai : les chromosomes qui migrent sont bichromatidiens (les chromatides sœurs restent unies).'),
  ('504972c4-f00c-57db-bbb0-189e0f59b65d', 'D', 'Correspond à la migration des chromosomes monochromatidiens', false, 'Faux : la migration de chromosomes monochromatidiens caractérise l''anaphase II.'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', 'A', 'disjonction des chromosomes bivalents', false, 'Faux : les bivalents se séparent en anaphase I.'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', 'B', 'dédoublement des chromosomes', true, 'Vrai : le dédoublement des chromosomes (clivage des centromères) a lieu en anaphase II.'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', 'C', 'séparation des chromatides', true, 'Vrai : les chromatides sœurs se séparent.'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', 'D', 'séparation des chromosomes homologues', false, 'Faux : les homologues se séparent en anaphase I.'),
  ('0514b60d-bc89-5641-8f48-502dc7762f05', 'E', 'déroulement du phénomène du crossing over', false, 'Faux : le crossing-over a lieu au pachytène de la prophase I.'),
  ('fa5f508c-2385-5144-8579-ff46c3b43388', 'A', '2n chromosome/4n chromatides /4n ADN', false, 'Faux : 2n chromosomes / 4n chromatides / 4n ADN correspond au spermatocyte I après réplication.'),
  ('fa5f508c-2385-5144-8579-ff46c3b43388', 'B', 'n chromosome/4n chromatides/ 4n ADN', false, 'Faux : avec n chromosomes bichromatidiens, on a 2n chromatides, pas 4n.'),
  ('fa5f508c-2385-5144-8579-ff46c3b43388', 'C', '2n chromosome/2n chromatides/2n ADN', false, 'Faux : 2n chromosomes monochromatidiens correspond à une cellule diploïde non répliquée (gonie en G1).'),
  ('fa5f508c-2385-5144-8579-ff46c3b43388', 'D', '4n chromosome/2n chromatides/2n AND', true, 'Retenue par le corrigé type, mais « 4n chromosomes » est faux : il faut lire n chromosomes / 2n chromatides / 2n ADN.'),
  ('1394f17f-77e1-569d-9cd9-2163801f655d', 'A', 'spermatide', true, 'Vrai : la spermatide, issue de la division II, est haploïde.'),
  ('1394f17f-77e1-569d-9cd9-2163801f655d', 'B', 'ovocyte II', true, 'Vrai : l''ovocyte II, issu de la division I, est haploïde (n chromosomes bichromatidiens).'),
  ('1394f17f-77e1-569d-9cd9-2163801f655d', 'C', 'spermatogonie', false, 'Faux : la spermatogonie est diploïde.'),
  ('1394f17f-77e1-569d-9cd9-2163801f655d', 'D', 'ovocyte I', false, 'Faux : l''ovocyte I est diploïde ; il est bloqué en prophase I.'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', 'A', 'concernent toutes les cellules germinales', false, 'Faux : les gonies se divisent par mitose ; seuls les cytes I entrent en méiose.'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', 'B', 'concernent quelques cellules somatiques', false, 'Faux : aucune cellule somatique ne fait de méiose.'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', 'C', 'permet la variabilité de l’espèce humaine', true, 'Vrai : les brassages inter- et intrachromosomique créent la variabilité.'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', 'D', 'permet la reconstitution de la diploïdie', false, 'Faux : la diploïdie est reconstituée par la fécondation.'),
  ('765747d5-b785-5c09-a541-da0a373a41ae', 'E', 'permet l’apparition de gamètes diploïdes', false, 'Faux : la méiose produit des gamètes haploïdes.'),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', 'A', 'les spermatocytes II', false, null),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', 'B', 'les cellules de Leydig', false, null),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', 'C', 'les ovocytes II', false, null),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', 'D', 'les ovogonies', false, null),
  ('371c503b-21e5-56ca-8f8e-ec24e5f2e614', 'E', 'les spermatocytes I', false, null),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', 'A', 'Concerne toutes les cellules, germinales', false, 'Faux : seules les cellules germinales engagées en méiose (cytes I) la réalisent.'),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', 'B', 'Permet le maintient du stock chromosomique', true, 'Vrai : avec la fécondation, elle maintient le stock chromosomique (46) de l''espèce.'),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', 'C', 'Concerne certaines cellules somatiques', false, 'Faux : les cellules somatiques ne font que des mitoses.'),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', 'D', 'Permet la reconstitution de la diploïdie', false, 'Faux : c''est la fécondation qui reconstitue la diploïdie.'),
  ('ce8bacda-1c46-597c-a2cf-089f7883d1c6', 'E', 'Permet l''apparition de gamètes diploïdes.', false, 'Faux : les gamètes sont haploïdes.'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', 'A', 'Les spermatocytes II', true, 'Vrai, c''est l''intrus : le spermatocyte II est haploïde.'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', 'B', 'Les cellules de Leydigs', false, 'Faux : les cellules de Leydig sont des cellules somatiques diploïdes.'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', 'C', 'Les ovocytes 1', false, 'Faux : l''ovocyte I est diploïde.'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', 'D', 'Les ovogonies', false, 'Faux : les ovogonies sont diploïdes.'),
  ('5bc1b962-b18d-5504-9390-1186b630ef66', 'E', 'Les spermatocytes I', false, 'Faux : le spermatocyte I est diploïde.'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', 'A', 'Maturation', false, 'Juste en réalité : la méiose correspond à la phase de maturation.'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', 'B', 'Différentiation', true, 'Retenue par le corrigé type, mais la différenciation (spermiogenèse) se déroule après la méiose.'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', 'C', 'Accroissement', false, 'Faux : l''accroissement précède la méiose.'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', 'D', 'Multiplication', false, 'Faux : la multiplication se fait par mitoses des gonies.'),
  ('b8d1c9dd-a733-57b1-b160-faa120ce6dfb', 'E', 'Prolifération', false, 'Faux : la prolifération est un autre nom de la multiplication.'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', 'A', 'Disjonction des chromosomes bivalents', false, 'Faux : les bivalents se séparent en anaphase I.'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', 'B', 'Dédoublement des centromères', true, 'Vrai : le dédoublement des centromères a lieu en anaphase II.'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', 'C', 'Séparation des chromatides', false, 'Juste en réalité : les chromatides sœurs se séparent en anaphase II.'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', 'D', 'Séparation des chromosomes homologues', true, 'Retenue par le corrigé type, mais la séparation des homologues caractérise l''anaphase I.'),
  ('84f790ef-062e-56ef-9654-a0bb2185eefb', 'E', 'Déroulement du phénomène du crossing over', false, 'Faux : le crossing-over a lieu au pachytène de la prophase I.'),
  ('71862bed-070f-5364-af8c-98b1e3e39551', 'A', 'Les spermatogonies renouvellent leurs stocks en se multipliant en continu par mitose', true, null),
  ('71862bed-070f-5364-af8c-98b1e3e39551', 'B', 'Dans l’expression spermatogonie Ad, Ad signifie noyau à aspect décoloré', false, null),
  ('71862bed-070f-5364-af8c-98b1e3e39551', 'C', 'Les spermatogonies Ad sont des spermatogonies de renouvellement qui se divisent en 2 spermatogonies B', false, null),
  ('71862bed-070f-5364-af8c-98b1e3e39551', 'D', 'Les spermatogonies B sont les dernières cellules qui se divisent par mitose', true, null),
  ('5b287451-a8ad-5c61-bf25-f8c5ed8269fe', 'A', 'Correspond à la phase de maturation des spermatozoïdes', false, null),
  ('5b287451-a8ad-5c61-bf25-f8c5ed8269fe', 'B', 'La plus grande partie du cytoplasme est éliminée sous forme de corps résiduels', true, null),
  ('5b287451-a8ad-5c61-bf25-f8c5ed8269fe', 'C', 'Elle aboutit à la formation des spermatozoïdes immédiatement fécondants', false, null),
