  ('6e6f439c-f361-568a-9056-1ff62eaf48d1', 'A', 'Les molécules lipophiles traversent la membrane plasmique sans intervention de protéines.', true, null),
  ('6e6f439c-f361-568a-9056-1ff62eaf48d1', 'B', 'Le passage des ions par les canaux ioniques est un exemple du transport actif.', false, null),
  ('6e6f439c-f361-568a-9056-1ff62eaf48d1', 'C', 'Le transport médié par les protéines nécessite toujours de l''ATP.', false, null),
  ('6e6f439c-f361-568a-9056-1ff62eaf48d1', 'D', 'L''équilibre hydrique est facilité par les aquaporines.', true, null),
  ('2190cc0a-a12f-5694-ac55-b100d7f02a04', 'A', 'Consiste en une diffusion simple.', false, null),
  ('2190cc0a-a12f-5694-ac55-b100d7f02a04', 'B', 'Est réalisé par des protéines.', true, null),
  ('2190cc0a-a12f-5694-ac55-b100d7f02a04', 'C', 'N''oppose jamais le gradient électrochimique du soluté.', false, null),
  ('2190cc0a-a12f-5694-ac55-b100d7f02a04', 'D', 'Permet la régulation de l''équilibre osmotique de la cellule.', true, null),
  ('1c30c33a-adb2-5ad1-98c1-fa33f029158a', 'A', 'Sont sélectifs.', true, null),
  ('1c30c33a-adb2-5ad1-98c1-fa33f029158a', 'B', 'Sont responsables de l''excitabilité électriques des cellules nerveuses et musculaires.', true, null),
  ('1c30c33a-adb2-5ad1-98c1-fa33f029158a', 'C', 'Sont couplés à une source d''énergie.', false, null),
  ('1c30c33a-adb2-5ad1-98c1-fa33f029158a', 'D', 'Fonctionnent selon un mode de transport passif.', true, null),
  ('e63e7fec-da67-5833-8296-2f056b35ce3b', 'A', 'Catalyse un antiports Na''/glucose.', false, null),
  ('e63e7fec-da67-5833-8296-2f056b35ce3b', 'B', 'Est localisé au pôle apical.', true, null),
  ('e63e7fec-da67-5833-8296-2f056b35ce3b', 'C', 'Permet I''absorption active du glucose.', true, null),
  ('e63e7fec-da67-5833-8296-2f056b35ce3b', 'D', 'Dépendant du gradient de H".', false, null),
  ('1e7c1d06-eeb1-590d-a4a3-c348fecb8529', 'B', 'Permet la sortie d''un ion Na''.', false, null),
  ('1e7c1d06-eeb1-590d-a4a3-c348fecb8529', 'C', 'Permet l''entrée d''un ion H.', false, null),
  ('1e7c1d06-eeb1-590d-a4a3-c348fecb8529', 'D', 'Participe à la régulation du pH intracellulaire.', true, null),
  ('d8ec04f4-9732-5454-a146-f553c526a005', 'A', 'Est totalement étanche (imperméable) à toute substance.', false, null),
  ('d8ec04f4-9732-5454-a146-f553c526a005', 'B', 'Régule les échanges entre le cytosol et le milieu extracellulaire.', true, null),
  ('d8ec04f4-9732-5454-a146-f553c526a005', 'C', 'Elle est fragile et facilement dissociable.', false, null),
  ('d8ec04f4-9732-5454-a146-f553c526a005', 'D', 'Joue un rôle crucial dans la communication cellulaire.', true, null),
  ('6b2e76ea-ce1b-574a-9717-452f82af5caf', 'A', 'La diffusion simple nécessite des canaux.', true, null),
  ('6b2e76ea-ce1b-574a-9717-452f82af5caf', 'B', 'La diffusion facilitée requiert de l''énergie sous forme d''ATP.', true, null),
  ('6b2e76ea-ce1b-574a-9717-452f82af5caf', 'C', 'Le sodium tend à rentrer dans la cellule et le potassium à en sortir.', false, null),
  ('6b2e76ea-ce1b-574a-9717-452f82af5caf', 'D', 'Les co-transporteurs permettent des échanges actifs secondaires.', false, null),
  ('8b88ee2d-ece1-522d-92ae-28f737bd5577', 'A', 'Le GLUT-1 est le principal transporteur du glucose dans les érythrocytes.', false, null),
  ('8b88ee2d-ece1-522d-92ae-28f737bd5577', 'B', 'Le GLUT-3 est essentiellement transcrit dans le système nerveux et la rétine.', false, null),
