  ('0a26591f-7c83-5468-9ce0-70e056679849', 'D', 'Son rôle est capital dans le fonctionnement du muscle cardiaque.', true, null),
  ('79473e15-d4a7-5a79-a10c-7a06f0ad0476', 'A', 'De la membrane plasmique (PMCA), fait sortir un ion calcium dans le milieu extracellulaire.', true, null),
  ('79473e15-d4a7-5a79-a10c-7a06f0ad0476', 'B', 'De la membrane plasmique (PMCA), fait entrer un ion calcium dans le cytosol.', false, null),
