  ('74bc0d80-24b6-5db9-b4e7-6fb3bac73845', 'A', 'la lidocaïne bloque le canal sodique voltage-dépendant.', false, null),
  ('74bc0d80-24b6-5db9-b4e7-6fb3bac73845', 'B', 'Le curare bloque le canal calcique voltage-dépendant.', true, null),
