  ('bca647d4-45b7-5687-82b6-ac96e32245ec', 'A', 'Ce sont des canaux ligand-dépendants', false, null),
  ('bca647d4-45b7-5687-82b6-ac96e32245ec', 'B', 'Leur ligand endogène est la muscarine', false, null),
  ('bca647d4-45b7-5687-82b6-ac96e32245ec', 'C', 'Ils sont retrouvés sur la membrane plasmique des cellules des muscles squelettiques', false, null),
  ('bca647d4-45b7-5687-82b6-ac96e32245ec', 'D', 'La fixation de leur ligand provoque l''ouverture des canaux sodiques de la membrane plasmique de la cellule cible', false, null),
  ('bca647d4-45b7-5687-82b6-ac96e32245ec', 'E', 'La fixation de leur ligand provoque une sortie de charges positives du cytosol vers le milieu extracellulaire et une hyperpolarisation de la cellule cible', true, null),
  ('4c68e211-f1f5-5132-b6df-e35b6b33eed5', 'A', 'Elles sont qualifiées d''hétérodimériques car elles sont composées de 2 sous-unités distinctes α et β', false, null),
  ('4c68e211-f1f5-5132-b6df-e35b6b33eed5', 'B', 'Ces trois sous unités sont dans un état dissociés (au repos)', false, null),
  ('4c68e211-f1f5-5132-b6df-e35b6b33eed5', 'C', 'La sous-unité β fixe les nucléotides guanyliques et possède l''activité GTPasique', false, null),
  ('4c68e211-f1f5-5132-b6df-e35b6b33eed5', 'D', 'La fixation du ligand sur te récepteur active l''activité ATPasique de la protéine G et provoque sa dissociation', false, null),
  ('4c68e211-f1f5-5132-b6df-e35b6b33eed5', 'E', 'Une fois dissociée des autres sous-unités, la sous-unité α est capable de moduler l''activité d''un effecteur primaire', true, null),
  ('21304265-3d7a-57d4-b411-26b52118b6bc', 'A', 'Ce sont des protéines à 4 domaines membranaires', false, null),
  ('21304265-3d7a-57d4-b411-26b52118b6bc', 'B', 'Leur ligand extracellulaire est une molécule hydrophile qualifiée de second messager', false, null),
  ('21304265-3d7a-57d4-b411-26b52118b6bc', 'C', 'Ils sont couplés à des protéines G monomériques', false, null),
  ('21304265-3d7a-57d4-b411-26b52118b6bc', 'D', 'Les protéines G couplées à ces récepteurs activent directement des effecteurs primaires pouvant être des canaux ou des enzymes', true, null),
  ('21304265-3d7a-57d4-b411-26b52118b6bc', 'E', 'Toutes les réponses sont fausses', false, null),
  ('ae05d251-78cb-58b4-aa5b-14238b8d7081', 'A', 'Il est présent à la surface des cellules post-synaptiques cardiaques', false, null),
  ('ae05d251-78cb-58b4-aa5b-14238b8d7081', 'B', 'C''est un canal ionique pentamérique et chacune de ses sous-unités possède 4 domaines transmembranaires', true, null),
  ('ae05d251-78cb-58b4-aa5b-14238b8d7081', 'C', 'La fixation de l''acétylcholine sur ses deux sous-unités y provoque l''ouverture du canal', false, null),
  ('ae05d251-78cb-58b4-aa5b-14238b8d7081', 'D', 'L''ouverture du canal provoque l''hyperpolarisation de la cellule musculaire et sa contraction', false, null),
  ('ae05d251-78cb-58b4-aa5b-14238b8d7081', 'E', 'Toutes ces réponses sont fausses', false, null),
  ('cf2ec6e1-90f3-5969-811c-e43f5aaa7d8a', 'A', 'Il est localisé dans la membrane plasmique des cellules musculaires', true, null),
  ('cf2ec6e1-90f3-5969-811c-e43f5aaa7d8a', 'B', 'C''est un récepteur enzyme', false, null),
  ('cf2ec6e1-90f3-5969-811c-e43f5aaa7d8a', 'C', 'Son ligand naturel est la nicotine', false, null),
  ('cf2ec6e1-90f3-5969-811c-e43f5aaa7d8a', 'D', 'Son agoniste est le Curare', false, null),
  ('cf2ec6e1-90f3-5969-811c-e43f5aaa7d8a', 'E', 'Toutes les réponses sont fausses', false, null),
