  ('43ca5558-1a32-5de1-b391-815a7d70859a', 'C', 'induisent des réponses de plus courte durée que leurs homologues hydrophiles', false, null),
  ('43ca5558-1a32-5de1-b391-815a7d70859a', 'D', 'régulent généralement la transcription des gènes', true, null),
  ('43ca5558-1a32-5de1-b391-815a7d70859a', 'E', 'Toutes ces réponses sont fausses', false, null),
