  ('34353655-2991-5435-bdd1-b01d3d19d5b0', 'C', 'A lieu uniquement lorsque les cellules sont proches dans l’espace.', false, null),
  ('34353655-2991-5435-bdd1-b01d3d19d5b0', 'D', 'La communication paracrine repose sur les ligands uniquement hydrophiles.', false, null),
  ('34353655-2991-5435-bdd1-b01d3d19d5b0', 'E', 'La communication endocrine est liée à la diffusion sur une longue distance de .', false, null),
  ('4f83265c-c613-5160-ab64-1896d6fca4fd', 'A', 'Un ligand peut se fixer sur plusieurs récepteurs.', true, null),
  ('4f83265c-c613-5160-ab64-1896d6fca4fd', 'B', 'Un récepteur peut fixer plusieurs ligands.', true, null),
  ('4f83265c-c613-5160-ab64-1896d6fca4fd', 'C', 'Les récepteurs couplés à la protéine G sont des récepteurs nucléaires.', false, null),
  ('4f83265c-c613-5160-ab64-1896d6fca4fd', 'D', 'Les récepteurs à activité tyrosine kinase font partie des récepteurs à activité enzymatique.', true, null),
  ('4f83265c-c613-5160-ab64-1896d6fca4fd', 'E', 'Tous les récepteurs nucléaires régulent l’expression des gènes.', true, null),
  ('d7b8afec-e867-5770-b847-3f97a24aebd9', 'A', 'Sont des récepteurs à 07 domaines transmembranaires.', true, null),
