  ('0073ca7a-d97b-58f2-85e4-83f54b47d3f2', 'A', 'Adrénaline.', false, null),
  ('0073ca7a-d97b-58f2-85e4-83f54b47d3f2', 'B', 'Diacylglycérol.', true, null),
  ('0073ca7a-d97b-58f2-85e4-83f54b47d3f2', 'C', 'Insuline.', false, null),
