  ('fbbfed52-26c3-52fe-afa0-97d9b33be246', 'E', 'Toutes les propositions sont fausses.', false, null),
  ('d3cee4bb-4d8a-541e-8f5b-d69e4421e30c', 'A', 'le récepteur est couple à une protéine Gs qui active la phospholipase', false, null),
  ('d3cee4bb-4d8a-541e-8f5b-d69e4421e30c', 'B', 'la PLC va cliver un PIP2 dans la membrane cellulaire en iP3 et en DAG, celui-ci tend à augmenter la concentration de calcium intra-cellulaire.', false, null),
  ('d3cee4bb-4d8a-541e-8f5b-d69e4421e30c', 'C', 'la protéine G fonctionne en utilisant un GDP', false, null),
  ('d3cee4bb-4d8a-541e-8f5b-d69e4421e30c', 'D', 'la protéine kinase A et la protéine kinase C ont la même action, celle de phosphoryler les protéines', true, null),
  ('d3cee4bb-4d8a-541e-8f5b-d69e4421e30c', 'E', 'une molécule de calmoduline peut fixer jusqu''à quatre ions calcium', true, null),
  ('566146d2-1bbb-5a45-94ea-342b062b6104', 'A', 'ces récepteurs sont formés d''une chaine d''acides amitiés traversant 7 fois la membrane plasmique', true, null),
  ('566146d2-1bbb-5a45-94ea-342b062b6104', 'B', 'les récepteurs peuvent être couplés à deux grandes voies d''amplification : une voie mettant en jeu l''adenylatecyclase et une autre mettant en jeu la phospholipase', true, null),
  ('566146d2-1bbb-5a45-94ea-342b062b6104', 'C', 'la fixation d''une hormone sur son récepteur, active l''adenylatecyclase pour favoriser la production d''IP3 afin d''initier une réponse biologique.', false, null),
  ('566146d2-1bbb-5a45-94ea-342b062b6104', 'D', 'la phosphodiestérase permet d''activer la protéine kinase A.', false, null),
  ('566146d2-1bbb-5a45-94ea-342b062b6104', 'E', 'toutes ces réponses sont fausses', false, null),
  ('db936edd-867e-58c9-97f0-04c9326664bb', 'A', 'ces récepteurs sont des récepteurs à 7 domaines dont la partie C-terminal est le site de liaison à l''hormone.', false, null),
  ('db936edd-867e-58c9-97f0-04c9326664bb', 'B', 'la protéine G peut être stimulatrice ou inhibitrice.', true, null),
  ('db936edd-867e-58c9-97f0-04c9326664bb', 'C', 'la sous unité alpha peut activer directement un canal ionique', false, null),
