  ('d52fa9a2-ca87-57f5-b6d3-e595296b94eb', 'A', 'ont une durez de vie très courte', false, null),
  ('d52fa9a2-ca87-57f5-b6d3-e595296b94eb', 'B', 'sont reconnues par des récepteurs spécifiques intracellulaires', false, null),
  ('d52fa9a2-ca87-57f5-b6d3-e595296b94eb', 'C', 'provoquent une réponse de courte durée', false, null),
  ('d52fa9a2-ca87-57f5-b6d3-e595296b94eb', 'D', 'ne traversent pas la membrane plasmique', false, null),
  ('d52fa9a2-ca87-57f5-b6d3-e595296b94eb', 'E', 'Toutes ces réponses sont fausses', false, null),
  ('81361460-d18f-5f88-833e-55e499b6bd21', 'A', 'circulent librement dans le sang', false, null),
  ('81361460-d18f-5f88-833e-55e499b6bd21', 'B', 'diffusent à travers la membrane plasmique et n’agissent pas par l''intermédiaire de récepteurs', false, null),
  ('81361460-d18f-5f88-833e-55e499b6bd21', 'C', 'induisent des réponses de plus longue durée que leurs homologues hydrophiles', false, null),
  ('81361460-d18f-5f88-833e-55e499b6bd21', 'D', 'régulent généralement la transcription des gènes', false, null),
  ('81361460-d18f-5f88-833e-55e499b6bd21', 'E', 'Toutes ces réponses sont fausses', false, null),
  ('ee1248d5-0bfd-5737-a6a0-2fc0ad540074', 'A', 'l’insuline', false, null),
  ('ee1248d5-0bfd-5737-a6a0-2fc0ad540074', 'B', 'Hormones stéroïdes', false, null),
  ('ee1248d5-0bfd-5737-a6a0-2fc0ad540074', 'C', 'Neurotransmetteurs', false, null),
  ('ee1248d5-0bfd-5737-a6a0-2fc0ad540074', 'D', 'Facteurs de croissance', false, null),
  ('ee1248d5-0bfd-5737-a6a0-2fc0ad540074', 'E', 'NO (monoxyde d''azote)', false, null),
  ('091cffba-4e00-5c12-bf15-44baf65e0f99', 'A', 'Le site de fixation de l''hormone hydrophile est localisé dans le domaine E', false, null),
  ('091cffba-4e00-5c12-bf15-44baf65e0f99', 'B', 'L''extrémité N-terminale est très conservée et agit comme un facteur de régulation de la transcription', false, null),
  ('091cffba-4e00-5c12-bf15-44baf65e0f99', 'C', 'Le signal de localisation nucléaire (NL5) est localisé dans le domaine D', false, null),
  ('091cffba-4e00-5c12-bf15-44baf65e0f99', 'D', 'le domaine de fixation à l''ADN a une structure en doigts de zinc', false, null),
  ('091cffba-4e00-5c12-bf15-44baf65e0f99', 'E', 'La région ERH (élément de réponse à l''hormone) est localisée dans le domaine C', false, null),
  ('1c57eb5d-397b-5873-81f6-aef2a38c627e', 'A', 'En absence de ligand, le récepteur a une localisation cytosolique', false, null),
  ('1c57eb5d-397b-5873-81f6-aef2a38c627e', 'B', 'En absence de ligand, le récepteur est dimérique', false, null),
  ('1c57eb5d-397b-5873-81f6-aef2a38c627e', 'C', 'En absence de ligand, le signal de localisation nucléaire (NLS) est masqué par des protéines associées au récepteur (PAR)', false, null),
  ('1c57eb5d-397b-5873-81f6-aef2a38c627e', 'D', 'La fixation du ligand entraine un changement de conformation du récepteur, une dissociation des PAR et une translocation du récepteur vers le noyau', false, null),
  ('1c57eb5d-397b-5873-81f6-aef2a38c627e', 'E', 'La fixation du ligand entraine la fixation du récepteur sur des séquences d''ADN appelées ERH (élément de réponse à l''hormone)', false, null),
  ('feae6633-ae32-5c74-ae72-4e93b810a610', 'A', 'est localisé dans la membrane plasmique des cellules musculaires', false, null),
  ('feae6633-ae32-5c74-ae72-4e93b810a610', 'B', 'Joue un rôle dans la contraction musculaire', false, null),
  ('feae6633-ae32-5c74-ae72-4e93b810a610', 'C', 'C''est un récepteur enzyme', false, null),
  ('feae6633-ae32-5c74-ae72-4e93b810a610', 'D', 'Son ligand naturel est l’acétylcholine', false, null),
  ('feae6633-ae32-5c74-ae72-4e93b810a610', 'E', 'il est impliqué dans la communication synaptique', false, null),
  ('bccc8c27-6863-5ce1-b5eb-fceaaec035f7', 'A', 'il est présent à la surface des cellules post-synaptiques dans les jonctions neuro-musuclaires', false, null),
  ('bccc8c27-6863-5ce1-b5eb-fceaaec035f7', 'B', 'c’est un canal ionique pentamérique et chacune de ses sous-unités possède à domaines transmembranaires', false, null),
  ('bccc8c27-6863-5ce1-b5eb-fceaaec035f7', 'C', 'En absence de son ligand spécifique, le canal est fermé', false, null),
  ('bccc8c27-6863-5ce1-b5eb-fceaaec035f7', 'D', 'La fixation de l''acétylcholine sur ses deux sous-unités y provoque l''ouverture du canal', false, null),
  ('bccc8c27-6863-5ce1-b5eb-fceaaec035f7', 'E', 'L''ouverture du canal provoque l''hyperpolarisation de la cellule musculaire et sa contractio', false, null),
  ('36eb2af1-1bf1-57c8-911b-8a5f7e0c0e11', 'A', 'Ce sont des protéines à 4 domaines membranaires', false, null),
  ('36eb2af1-1bf1-57c8-911b-8a5f7e0c0e11', 'B', 'leur ligand extracellulaire est une molécule hydrophile qualifiée de second messager', false, null),
  ('36eb2af1-1bf1-57c8-911b-8a5f7e0c0e11', 'C', 'ils sont couplé à des protéines G monomériques', false, null),
  ('36eb2af1-1bf1-57c8-911b-8a5f7e0c0e11', 'D', 'les protéines G couplés à ces récepteurs activent directement des effecteurs primaires pouvant être des canaux ou des enzymes', false, null),
  ('36eb2af1-1bf1-57c8-911b-8a5f7e0c0e11', 'E', 'Leurs activation entraine une amplification du signal', false, null),
  ('72fc6b68-059d-5b42-85b3-447178798974', 'A', 'Elles sont qualifiées d''hétérotrimériques car elles sont composées de 3 sous-unités distinctes : α, β et γ', false, null),
  ('72fc6b68-059d-5b42-85b3-447178798974', 'B', 'ces trois sous unités sont dans un état dissociés (au repos)', false, null),
  ('72fc6b68-059d-5b42-85b3-447178798974', 'C', 'la sous-unité β fixe les nucléotides guanyliques et possède l’activité GTPasique', false, null),
  ('72fc6b68-059d-5b42-85b3-447178798974', 'D', 'la fixation du ligand sur le récepteur active l''activité GTPasique de la protéine G et provoque sa dissociation', false, null),
  ('72fc6b68-059d-5b42-85b3-447178798974', 'E', 'Une fois dissociée des deux autres sous-unités, la sous-unité α est capable de moduler l''activité d''un effecteur primaire', false, null),
  ('8d54486e-9a76-539e-84f5-a77e9607e5e2', 'A', 'Activation de l’adénylate cyclase par le dimère de sous-unités β et γ →Synthèse d''AMPc à partir d''ATP → Activation de la PKA → Phosphorylation des substrats de la PKA', false, null),
  ('8d54486e-9a76-539e-84f5-a77e9607e5e2', 'B', 'Activation de l''adénylate cyclase par la sous-unité α → Synthèse d''AMPc à partir d''ATP →Fixation de l’AMPc sur son récepteur de la membrane du REL →Augmentation de la concentration cytosolique de Ca2+ →Activation de la PKC →Phosphorylation des substrats de la PKC', false, null),
  ('8d54486e-9a76-539e-84f5-a77e9607e5e2', 'C', 'Activation de l''adénylate cyclase par la sous-unité α →Synthèse d''AMPc à partir d''ATP→ Activation de la PKA →Phosphorylation des substrats de la PKA', false, null),
  ('8d54486e-9a76-539e-84f5-a77e9607e5e2', 'D', 'Activation de l''adénylate cyclase par la sous-unité α →Synthèse d''AMPc à partir d''ATP →Activation de la PKC →Phosphorylation des substrats de la PKA C', false, null),
  ('8d54486e-9a76-539e-84f5-a77e9607e5e2', 'E', 'Activation de l’adénylate cyclase par le dimère de sous-unités β et γ →Synthèse d''AMPc à partir d''ATP → Fixation de l’AMPc sur son récepteur de la membrane du REL → Augmentation de la concentration cytosolique de Ca2+ → Activation de la CAM kinase → Phosphorylation des substrats de la Cam kinase', false, null),
  ('49bf7338-88a9-5a2b-8ed5-70e92b402e72', 'A', 'Activation de la PLC → Synthèse d''IP3 et de DAG à partir de PIP2 → Activation de la PKA → Phosphorylation des substrats de la PKA', false, null),
  ('49bf7338-88a9-5a2b-8ed5-70e92b402e72', 'B', 'Activation de la PLC → Synthèse d''IP3 à partir de PIP2 → Activation de la PKC → Phosphorylation des substrats de la PKC', false, null),
  ('49bf7338-88a9-5a2b-8ed5-70e92b402e72', 'C', 'Activation de la PLC→ Synthèse d''IP3 à partir de PIP2 → Fixation de l’IP3 sur son récepteur de la membrane du REL → Augmentation de la concentration cytosolique de Ca2+ → Fixation du Ca2+ sur la calmoduline → Activation de la CAM kinase → Phosphorylation des substrats de la Cam kinase', false, null),
  ('49bf7338-88a9-5a2b-8ed5-70e92b402e72', 'D', 'Activation de la PLC→ Synthèse d''IP3 à partir de PIP2 → Fixation de l’IP3 sur son récepteur de la membrane du REL → Diminution de la concentration cytosolique de Ca2+ → Inhibition de la Cam Kinase', false, null),
  ('49bf7338-88a9-5a2b-8ed5-70e92b402e72', 'E', 'Activation de la PLC → Synthèse de DAG à partir de PIP2 → Activation de la PKC → Phosphorylation des substrats de la PKC', false, null),
  ('4b93ab49-c434-5bf0-93eb-e77a83c45be3', 'A', 'Ce sont des canaux ligand-dépendants', false, null),
  ('4b93ab49-c434-5bf0-93eb-e77a83c45be3', 'B', 'Leur ligand endogène est la muscarine', false, null),
  ('4b93ab49-c434-5bf0-93eb-e77a83c45be3', 'C', 'Ils sont retrouvés sur la membrane plasmique des cellules des muscles cardiaques', false, null),
  ('4b93ab49-c434-5bf0-93eb-e77a83c45be3', 'D', 'La fixation de leur ligand provoque l''ouverture des canaux potassiques de la membrane plasmique de la cellule cible', false, null),
  ('4b93ab49-c434-5bf0-93eb-e77a83c45be3', 'E', 'La fixation de leur ligand provoque une sortie de charges positives du cytosol vers le milieu extracellulaire et une hyperpolarisation de la cellule cible', false, null),
  ('54e96560-4c45-5fb4-ac3f-7c2e0fd1dca7', 'A', 'Ce sont des récepteurs enzymes à activité tyrosine kinase', false, null),
  ('54e96560-4c45-5fb4-ac3f-7c2e0fd1dca7', 'B', 'La fixation de leur ligand entraine leur dimérisation et leur activation', false, null),
  ('54e96560-4c45-5fb4-ac3f-7c2e0fd1dca7', 'C', 'la fixation de leur ligand entraîne l''activation de la protéine G Ras par l''intermédiaire de Grb2 et Sos', false, null),
  ('54e96560-4c45-5fb4-ac3f-7c2e0fd1dca7', 'D', 'la fixation de leur ligand induit des phosphorylations en chaîne et aboutit à l''activation d''une MAP kinase', false, null),
  ('54e96560-4c45-5fb4-ac3f-7c2e0fd1dca7', 'E', 'Leur activation module la transcription de gènes cibles', false, null),
  ('058c908d-c882-5d66-bd47-28400bb81318', 'A', '20%.', false, null),
  ('058c908d-c882-5d66-bd47-28400bb81318', 'B', '40 %.', false, null),
  ('058c908d-c882-5d66-bd47-28400bb81318', 'C', '15 %', true, null),
  ('058c908d-c882-5d66-bd47-28400bb81318', 'D', '5%.', false, null),
  ('c3fe8184-6cf1-57cb-bff6-a6681f8313b9', 'A', 'Le sodium est majoritairement intracellulaire.', false, null),
  ('c3fe8184-6cf1-57cb-bff6-a6681f8313b9', 'B', 'le chlore est majoritairement extracellulaire.', true, null),
