  ('013286b0-5ac5-5842-a029-43d5bc0b0535', 'D', 'Son osmolarité est supérieure à cellule du plasma.', false, null),
  ('e2acc336-9500-59db-9a72-bba2f7842983', 'A', 'Représente 20 % du poids corporel.', false, null),
  ('e2acc336-9500-59db-9a72-bba2f7842983', 'B', 'Est riche en protéines.', false, null),
  ('e2acc336-9500-59db-9a72-bba2f7842983', 'C', 'Est de composition ionique identique à celle du plasma.', true, null),
  ('e2acc336-9500-59db-9a72-bba2f7842983', 'D', 'Est synonyme de la lymphe.', false, null),
  ('20609ba8-6c91-5822-a684-2bff955308ce', 'A', 'Est due, dans le plasma, aux sels de sodium.', false, null),
  ('20609ba8-6c91-5822-a684-2bff955308ce', 'B', 'Est plus élevé dans le secteur interstitiel que vasculaire.', false, null),
  ('20609ba8-6c91-5822-a684-2bff955308ce', 'C', 'S''oppose à la sortie d''eau hors des capillaires.', true, null),
  ('20609ba8-6c91-5822-a684-2bff955308ce', 'D', 'Sa diminution est à l''origine d''apparition d''œdèmes.', true, null),
  ('0eed421a-d5e0-5a1a-a23a-4c1adef465b7', 'A', 'On assiste à une sortie de liquide vers l''interstitium.', true, null),
  ('0eed421a-d5e0-5a1a-a23a-4c1adef465b7', 'B', 'On assiste à un phénomène de filtration.', true, null),
