  ('0eed421a-d5e0-5a1a-a23a-4c1adef465b7', 'D', 'On assiste à un phénomène de réabsorption. Anciennes Questions 2010-2022', false, null),
  ('e0e58b1e-12af-52ac-8dac-acb28be6d0da', 'A', 'Il s’agit de l’association du secteur intracellulaire et du secteur extracellulaire.', false, null),
  ('e0e58b1e-12af-52ac-8dac-acb28be6d0da', 'B', 'Est un milieu de composition homogène.', false, null),
  ('e0e58b1e-12af-52ac-8dac-acb28be6d0da', 'C', 'composition est maintenue stable grâce aux systèmes de contrôles homéostatiques.', true, null),
  ('e0e58b1e-12af-52ac-8dac-acb28be6d0da', 'D', 'Le volume du compartiment transcellulaire est plus grand que le volume plasmatique.', false, null),
  ('e0e58b1e-12af-52ac-8dac-acb28be6d0da', 'E', 'Son volume est plus important chez le nourrisson et la femme enceinte.', true, null),
  ('b1db97b9-0001-58e7-b93a-ed1684e96f94', 'A', 'Du liquide extracellulaire est égal à 12L.', true, null),
