  ('b1db97b9-0001-58e7-b93a-ed1684e96f94', 'D', 'Du secteur interstitiel est égal à 9L.', true, null),
  ('b1db97b9-0001-58e7-b93a-ed1684e96f94', 'E', 'Toutes les propositions sont justes .', false, null),
  ('b0d03ec1-1592-5176-b5af-b4a15f7dd61d', 'A', 'Les protéines sanguines représentent environ 50% des osmoles du plasma .', true, null),
  ('b0d03ec1-1592-5176-b5af-b4a15f7dd61d', 'B', 'Le potassium est le principal cation du liquide interstitiel.', true, null),
  ('b0d03ec1-1592-5176-b5af-b4a15f7dd61d', 'C', 'Les protéines sont les principaux tampons du secteurs plasmatique.', true, null),
  ('b0d03ec1-1592-5176-b5af-b4a15f7dd61d', 'D', 'La natrémie est le principal déterminant de l’osmolarité extracellulaire.', false, null),
  ('b0d03ec1-1592-5176-b5af-b4a15f7dd61d', 'E', 'Il existe un gradient de sodium entre le milieu interstitiel et le milieu intracellulaire .', false, null),
  ('91313924-3d0c-54fa-a093-33815aadcbbf', 'A', 'Il est riche en chlore et pauvre en potassium.', false, null),
  ('91313924-3d0c-54fa-a093-33815aadcbbf', 'B', 'Il est riche en sodium et pauvre en phosphate.', false, null),
  ('91313924-3d0c-54fa-a093-33815aadcbbf', 'C', 'Comprend le liquide intravasculaire et le liquide interstitiel.', false, null),
  ('91313924-3d0c-54fa-a093-33815aadcbbf', 'D', 'Représente 1/3 des liquides de l’organismes.', false, null),
  ('91313924-3d0c-54fa-a093-33815aadcbbf', 'E', 'Toutes les propositions sont justes.', false, null),
  ('a2ce494a-7eec-5353-adb5-785ac846179a', 'A', 'Les entrées d’eau sont régulées par la soif.', true, null),
  ('a2ce494a-7eec-5353-adb5-785ac846179a', 'B', 'L’eau plasmatique fait partie du compartiment interstitiel et représente 4% du poids corporel.', false, null),
  ('a2ce494a-7eec-5353-adb5-785ac846179a', 'C', 'Comprend le liquide intravasculaire et le liquide interstitiel.', true, null),
  ('a2ce494a-7eec-5353-adb5-785ac846179a', 'D', 'Représente 1/3 des liquides de l’organismes.', true, null),
  ('a2ce494a-7eec-5353-adb5-785ac846179a', 'E', 'Toutes les propositions sont justes.', false, null),
  ('91ec13a3-8c0b-5cac-a3c9-bd175db91b1c', 'A', 'Il y a des échanges permanents entre le milieu extérieur et le milieu intérieur .', true, null),
  ('91ec13a3-8c0b-5cac-a3c9-bd175db91b1c', 'B', 'Les échanges se font par diffusion au niveau des artères.', false, null),
  ('91ec13a3-8c0b-5cac-a3c9-bd175db91b1c', 'C', 'La pression hydrostatique est la pression exercée par le sang à l’extérieur des vaisseaux', false, null),
  ('91ec13a3-8c0b-5cac-a3c9-bd175db91b1c', 'D', 'La pression osmotique diminue lorsqu’on s’éloigne du cœur.', false, null),
  ('91ec13a3-8c0b-5cac-a3c9-bd175db91b1c', 'E', 'L’O₂, les nutriments et l’albumine passent du liquide intra vasculaire vers le liquides interstitiel.', false, null),
  ('f2d332d3-3e50-5088-8330-98c5e002dc0b', 'A', 'Est un secteur du compartiment intracellulaire.', false, null),
  ('f2d332d3-3e50-5088-8330-98c5e002dc0b', 'B', 'A une composition ionique proche de celle du plasma.', true, null),
  ('f2d332d3-3e50-5088-8330-98c5e002dc0b', 'C', 'Ne contient pas de protéines .', false, null),
  ('f2d332d3-3e50-5088-8330-98c5e002dc0b', 'D', 'Permet la réabsorption de 50% du liquide filtré sur le versant artériolaire de réseau capillaire.', false, null),
  ('f2d332d3-3e50-5088-8330-98c5e002dc0b', 'E', 'Rejoint la circulation sanguine.', true, null),
  ('9ab91c17-4ab3-5143-8985-7b39a3b5e84e', 'A', 'L’eau représente 70 % du poids du corps soit 42 L pour un homme', false, null),
  ('9ab91c17-4ab3-5143-8985-7b39a3b5e84e', 'B', 'Un adulte de 80 Kg possède 48L d’eau.', true, null),
  ('9ab91c17-4ab3-5143-8985-7b39a3b5e84e', 'C', 'La teneur du corps en eau augmente progressivement avec l’âge.', false, null),
  ('9ab91c17-4ab3-5143-8985-7b39a3b5e84e', 'D', 'Chez un nouveau-né, le LEC représente 40 % de l’eau corporelle totale.', true, null),
  ('9ab91c17-4ab3-5143-8985-7b39a3b5e84e', 'E', 'La composante extracellulaire et intravasculaire correspond au plasma.', true, null),
  ('670454c8-b83b-5dd0-a935-1979df2a4574', 'A', 'Son volume est de 28 L chez un adulte de 70 Kg.', true, null),
  ('670454c8-b83b-5dd0-a935-1979df2a4574', 'B', 'Il est pauvre en protéines', false, null),
  ('670454c8-b83b-5dd0-a935-1979df2a4574', 'C', 'Il est riche en K+', true, null),
  ('670454c8-b83b-5dd0-a935-1979df2a4574', 'D', 'Il est pauvre en C', true, null),
  ('670454c8-b83b-5dd0-a935-1979df2a4574', 'E', 'Son osmolarité est supérieure à celle du plasma.', false, null),
  ('b1e20b08-95fb-5682-a6a3-99b8a46d150f', 'A', 'Son volume est de 3,5 L chez un adulte de 70 Kg.', false, null),
  ('b1e20b08-95fb-5682-a6a3-99b8a46d150f', 'B', 'll est riche en protéines.', false, null),
  ('b1e20b08-95fb-5682-a6a3-99b8a46d150f', 'C', 'Il est riche en Na+', true, null),
  ('b1e20b08-95fb-5682-a6a3-99b8a46d150f', 'D', 'Il est pauvre en K+.', true, null),
  ('b1e20b08-95fb-5682-a6a3-99b8a46d150f', 'E', 'Son osmolarité est inférieure à celle du secteur intracellulaire.', false, null),
  ('9f52f485-1fff-549b-a659-0ad92b72f750', 'A', 'Les synapses sont toujours unidirectionnelles, ce qui permet de diriger des signaux vers des cibles spécifiques.', false, null),
  ('9f52f485-1fff-549b-a659-0ad92b72f750', 'B', 'La libération des vésicules des terminaisons présynaptiques est permise par la forte densité en canaux calciques ligand-dépendants.', false, null),
  ('9f52f485-1fff-549b-a659-0ad92b72f750', 'C', 'Un neurotransmetteur activateur peut entrainer soit une ouverture des canaux sodium soit une fermeture des canaux potassium ou des canaux chlore.', true, null),
  ('9f52f485-1fff-549b-a659-0ad92b72f750', 'D', 'L''ouverture des canaux potassiques provoque un potentiel post-synaptique inhibiteur (PPSI) par diminution de la charge de la cellule.', true, null),
  ('94fd0303-e4ab-5ee2-9e2e-63efe18dc7cf', 'A', 'L''arrivée du potentiel d''action pré-synaptique provoque une libération de calcium dans la fente synaptique.', false, null),
  ('94fd0303-e4ab-5ee2-9e2e-63efe18dc7cf', 'B', 'Le médiateur chimique libéré se fixe au niveau de la plaque motrice sur un récepteur chimiodépendant cholinergique de type nicotinique.', true, null),
  ('94fd0303-e4ab-5ee2-9e2e-63efe18dc7cf', 'C', 'Après son action, l''acétylcholine est détruite au niveau des récepteurs cholinergiques nicotiniques par l''acétylcholine transférase.', false, null),
  ('94fd0303-e4ab-5ee2-9e2e-63efe18dc7cf', 'D', 'La nicotine, comme le curare, est un agoniste de l''acétylcholine.', false, null),
  ('9d3cc82d-861e-567c-9904-965a3107eaf3', 'A', 'Elle est plus rapide sur les fibres A6 que sur les fibres C.', false, null),
  ('9d3cc82d-861e-567c-9904-965a3107eaf3', 'B', 'Elle est proportionnelle à la racine carrée du diamètre des S axones.', false, null),
  ('9d3cc82d-861e-567c-9904-965a3107eaf3', 'C', 'Elle se fait en raison e courants locaux de neud de Ranvier à neud de Ranvier.', true, null),
  ('9d3cc82d-861e-567c-9904-965a3107eaf3', 'D', 'Elle peut être di-directionnelle si on provoque expérimentalement l''apparition des potentiels d''action.', true, null),
  ('d12bdd28-cc10-5948-8f1e-49b07fc2a42a', 'A', 'Pour la synapse électrique, la conduction des potentiels d''action est unidirectionnelle.', false, null),
  ('d12bdd28-cc10-5948-8f1e-49b07fc2a42a', 'B', 'Le délai de transmission des signaux est plus court dans une synapse chimique que dans une synapse électrique.', false, null),
  ('d12bdd28-cc10-5948-8f1e-49b07fc2a42a', 'C', 'La cellule post-synaptique d''une synapse chimique ne possède que des canaux ioniques couplés aux récepteurs synaptiques.', false, null),
  ('d12bdd28-cc10-5948-8f1e-49b07fc2a42a', 'D', 'Il existe pour certaines synapses chimiques des autorécepteurs pour le médiateur chimique qui sont situés au niveau de la terminaison pré-synaptique et qui exercent un rétrocontrôle de la libération de ce médiateur chimique.', true, null),
  ('a7eb13c5-78cf-56cc-915c-10a7d312312d', 'A', 'La quantité d''acétylcholine qui est libérée par un potentiel d''action pré-synaptique est qui se fixe sur le récepteur muscarinique de la plaque motrice de la fibre striée squelettique est beaucoup plus importante que celle nécessaire pour obtenir un potentiel d''action musculaire.', false, null),
  ('a7eb13c5-78cf-56cc-915c-10a7d312312d', 'B', 'La synthèse de l''acétylcholine dans l''élément post-synaptique est assurée par l''enzyme acétylcholine estérase', false, null),
  ('a7eb13c5-78cf-56cc-915c-10a7d312312d', 'C', 'Le curare est utilisé pour mettre en évidence le potentiel de plaque motrice parce que c''est un inhibiteur compétitif de l''acétylcholine.', true, null),
  ('a7eb13c5-78cf-56cc-915c-10a7d312312d', 'D', 'L''atteinte du seuil d''ouverture des canaux voltage-dépendants du sarcolemme permet la naissance et la propagation du potentiel d''action musculaire.', true, null),
  ('4770a273-bb25-5e39-b5c8-73af212fdd13', 'A', 'L''AMPA est un agoniste exogène.', false, null),
  ('4770a273-bb25-5e39-b5c8-73af212fdd13', 'B', 'Son activation excessive peut induire la nécrose', true, null),
  ('4770a273-bb25-5e39-b5c8-73af212fdd13', 'C', 'Est un récepteur inotrope.', true, null),
  ('4770a273-bb25-5e39-b5c8-73af212fdd13', 'D', 'Son ligand naturel est la sérotonine.', false, null),
  ('39c6cf26-2f2e-5c66-a5ca-ebbe06c18c88', 'A', 'Est un récepteur métabotrope.', false, null),
  ('39c6cf26-2f2e-5c66-a5ca-ebbe06c18c88', 'B', 'Sa stimulation est associée à une entrée de chlorures dans le neurone postsynaptique.', true, null),
  ('39c6cf26-2f2e-5c66-a5ca-ebbe06c18c88', 'C', 'Sa stimulation est associée à l’apparition d''un potentiel post-synaptique inhibiteur (PPS).', true, null),
  ('39c6cf26-2f2e-5c66-a5ca-ebbe06c18c88', 'D', 'Son activité peut être bloquée par la tétrodotoxine.', false, null),
  ('b99c83c7-9ec9-51ba-a761-6f09fa66f3d1', 'A', 'la lidocaïne bloque le canal sodique voltage-dépendant.', false, null),
  ('b99c83c7-9ec9-51ba-a761-6f09fa66f3d1', 'B', 'Le curare bloque le canal calcique voltage-dépendant.', true, null),
  ('b99c83c7-9ec9-51ba-a761-6f09fa66f3d1', 'C', 'la tétrodotoxine bloque le canal sodique ligand-dépendant.', true, null),
  ('b99c83c7-9ec9-51ba-a761-6f09fa66f3d1', 'D', 'l''ouabaïne bloque la pompe Na''/Ka.', false, null),
  ('30c3bfa3-7a85-5791-bc15-93184f1d6fe4', 'B', 'Le neurone présynaptique libère du glutamate.', false, null),
  ('30c3bfa3-7a85-5791-bc15-93184f1d6fe4', 'C', 'le curare peut la bloquer.', true, null),
  ('30c3bfa3-7a85-5791-bc15-93184f1d6fe4', 'D', 'L''atropine peut la bloquer.', false, null),
  ('eaffcde2-a661-5acc-bb60-db4c562afc9a', 'A', 'elles peuvent être activatrices ou inhibitrices.', true, null),
  ('eaffcde2-a661-5acc-bb60-db4c562afc9a', 'B', 'la jonction neuromusculaire est une synapse neuro-effectrice.', true, null),
  ('eaffcde2-a661-5acc-bb60-db4c562afc9a', 'C', 'au niveau des synapses électriques, le message est transmis par des courants ioniques.', true, null),
  ('eaffcde2-a661-5acc-bb60-db4c562afc9a', 'D', 'lors de la libération du neurotransmetteur, on observe le déclenchement d''un potentiel d''action au niveau de la membrane post synaptique.', false, null),
  ('0efff520-9e2c-57d6-ad5d-988889e680c9', 'A', 'L’entrée de Ca2+ au niveau de l''élément post synaptique entraîne la production d''un potentiel post synaptique excitateur (PPSE).', true, null),
  ('0efff520-9e2c-57d6-ad5d-988889e680c9', 'B', 'Les vésicules contenues dans I''élément post synaptique contiennent un seul type de neuromédiateur.', false, null),
  ('0efff520-9e2c-57d6-ad5d-988889e680c9', 'C', 'L’augmentation du Ca2+ intracellulaire provoque I''exocytose du neurotransmetteur.', true, null),
  ('0efff520-9e2c-57d6-ad5d-988889e680c9', 'D', 'les canaux calciques situés sur la membrane pré synaptique sont voltage dépendant Anciennes Questions 2010-2022', true, null),
  ('b26b0d64-27f6-5492-8cf8-b481c5e8ada7', 'A', 'Elles sont toujours unidirectionnelles.', false, null),
  ('b26b0d64-27f6-5492-8cf8-b481c5e8ada7', 'B', 'Elles peuvent être activatrices ou inhibitrices.', true, null),
  ('b26b0d64-27f6-5492-8cf8-b481c5e8ada7', 'C', 'La jonction neuromusculaire est une synapse neuro-effectrice', true, null),
  ('b26b0d64-27f6-5492-8cf8-b481c5e8ada7', 'D', 'Au niveau des synapses électriques, le message est transmis par des courants ioniques.', true, null),
  ('b26b0d64-27f6-5492-8cf8-b481c5e8ada7', 'E', 'Lors de la libération du neurotransmetteur, on observe le déclenchement d’un potentiel d’action au niveau de la membrane post synaptique', false, null),
  ('f372e221-e442-59ba-9975-4b9239ba0c93', 'A', 'L’entrée de Ca » au niveau de l’élément post-synaptique entraine la production d’un potentiel Post synaptique excitateur (PPSE).', true, null),
  ('f372e221-e442-59ba-9975-4b9239ba0c93', 'B', 'Les vésicules contenues dans l’élément post-synaptique contiennent un seul type de Neuromédiateur.', false, null),
  ('f372e221-e442-59ba-9975-4b9239ba0c93', 'C', 'L’augmentation du Ca2* intracellulaire provoque l’exocytose du neurotransmetteur.', true, null),
  ('f372e221-e442-59ba-9975-4b9239ba0c93', 'D', 'Les canaux calciques situés sur la membrane pré synaptique sont voltage dépendant.', true, null),
  ('f372e221-e442-59ba-9975-4b9239ba0c93', 'E', 'Toutes ces réponses sont fausses.', false, null),
  ('a80208c9-c56a-50a1-8327-6fe2b755e679', 'A', 'l''entrée de Ca++ au niveau de l''élément post synaptique entraine la production d''un potentiel post synaptique excitateur (PPSE).', false, null),
  ('a80208c9-c56a-50a1-8327-6fe2b755e679', 'B', 'l''augmentation du Ca++ intracellulaire provoque l''exocytose du neurotransmetteur.', false, null),
  ('a80208c9-c56a-50a1-8327-6fe2b755e679', 'C', 'les canaux calciques situés sur la membrane pré-synaptique sont voltage dépendant', true, null),
  ('a80208c9-c56a-50a1-8327-6fe2b755e679', 'D', 'toutes ces réponses sont fausses', true, null),
  ('95b307f7-304d-57bd-ad29-3eec5ad9da87', 'A', 'Elle est I''effecteur du système nerveux somatique.', true, null),
  ('95b307f7-304d-57bd-ad29-3eec5ad9da87', 'B', 'Elle a un potentiel d''action dont la durée est plus courte que celle du potentiel d''action de la fibre nerveuse myélinisée qui l''innerve.', false, null),
  ('95b307f7-304d-57bd-ad29-3eec5ad9da87', 'C', 'Elle conduit des potentiels d''action avec une vitesse inférieure à la vitesse à laquelle la fibre nerveuse myélinisée qui l''innerve, conduit les potentiels d''action nerveux.', true, null),
  ('95b307f7-304d-57bd-ad29-3eec5ad9da87', 'D', 'Elle possède la propriété de se laisser déformer sous l''effet d''une force et de ne pas reprendre sa forme lorsque la force est supprimée.', false, null),
  ('0b0e39ee-2c5f-52dd-885f-28cc2f77cf40', 'A', 'L''arrivée du potentiel d''action pré-synaptique provoque une libération de calcium dans la fente synaptique.', false, null),
  ('0b0e39ee-2c5f-52dd-885f-28cc2f77cf40', 'B', 'Le médiateur chimique libéré se fixe au niveau de la plaque motrice sur un récepteur chimiodépendant cholinergique de type nicotinique.', true, null),
  ('0b0e39ee-2c5f-52dd-885f-28cc2f77cf40', 'C', 'Après son action, l''acétylcholine est détruite au niveau des récepteurs cholinergiques nicotiniques par l''acétylcholine transférase.', false, null),
  ('0b0e39ee-2c5f-52dd-885f-28cc2f77cf40', 'D', 'La nicotine, comme le curare, est un agoniste de l''acétylcholine.', false, null),
  ('47896ef1-c681-52ff-a757-3889378e6eb2', 'A', 'La quantité d''acétylcholine qui est libérée par un potentiel d''action pré-synaptique est qui se fixe sur le récepteur muscarinique de la plaque motrice de la fibre striée squelettique est beaucoup plus importante que celle nécessaire pour obtenir un potentiel d''action musculaire.', false, null),
  ('47896ef1-c681-52ff-a757-3889378e6eb2', 'B', 'La synthèse de l''acétylcholine dans l''élément post-synaptique est assurée par l''enzyme acétylcholine estérase', false, null),
  ('47896ef1-c681-52ff-a757-3889378e6eb2', 'C', 'Le curare est utilisé pour mettre en évidence le potentiel de plaque motrice parce que c''est un inhibiteur compétitif de l''acétylcholine.', true, null),
  ('47896ef1-c681-52ff-a757-3889378e6eb2', 'D', 'L''atteinte du seuil d''ouverture des canaux voltage-dépendants du sarcolemme permet la naissance et la propagation du potentiel d''action musculaire. La Jonctions Neuromusculaire', true, null),
  ('424168e9-5c1f-5639-90f9-ecb6daa576b4', 'B', 'Le neurone présynaptique libère du glutamate.', false, null),
  ('424168e9-5c1f-5639-90f9-ecb6daa576b4', 'C', 'le curare peut la bloquer.', true, null),
  ('424168e9-5c1f-5639-90f9-ecb6daa576b4', 'D', 'L''atropine peut la bloquer.', false, null),
  ('d640d041-bde5-5eab-9941-103fd31c2bb1', 'A', 'Le corps cellulaire du motoneurone se trouve dans la corne antérieure.', true, null),
  ('d640d041-bde5-5eab-9941-103fd31c2bb1', 'B', 'on peut trouver plusieurs plaques motrices par fibre musculaire striée squelettique.', false, null),
  ('d640d041-bde5-5eab-9941-103fd31c2bb1', 'C', 'au niveau de certaines plaques motrices, l''acétylcholine peut avoir un effet inhibiteur', false, null),
  ('d640d041-bde5-5eab-9941-103fd31c2bb1', 'D', 'les récepteurs cholinergiques à ce niveau sont de type nicotinique Anciennes Questions 2010-2022', true, null),
  ('6393ba6a-dc64-585b-8a36-c71a558a4d94', 'A', 'Le corps cellulaire du motoneurone se trouve dans la corne antérieure de la moelle épinière.', false, null),
  ('6393ba6a-dc64-585b-8a36-c71a558a4d94', 'B', 'On peut trouver plusieurs plaques motrices par fibre musculaire striée squelettique.', false, null),
  ('6393ba6a-dc64-585b-8a36-c71a558a4d94', 'C', 'Au niveau de certaines plaques motrices, l’acétylcholine peut avoir un effet inhibiteur.', false, null),
  ('6393ba6a-dc64-585b-8a36-c71a558a4d94', 'D', 'Les récepteurs cholinergiques à ce niveau sont de type muscarinique.', false, null),
  ('6393ba6a-dc64-585b-8a36-c71a558a4d94', 'E', 'Toutes ces réponses sont fausses.', true, null),
  ('9ab59627-bd83-5d8a-ae3d-13a22f9d3547', 'A', 'le corps cellulaire du neurone se trouve dans la corne postérieure de la moelle épinière', false, null),
  ('9ab59627-bd83-5d8a-ae3d-13a22f9d3547', 'B', 'on peut trouver plusieurs plaques motrices par fibre musculaire striée squelettique.', false, null),
  ('9ab59627-bd83-5d8a-ae3d-13a22f9d3547', 'C', 'au niveau de certaines plaques motrices, l''acétylcholine peut avoir un effet inhibiteur', false, null),
  ('9ab59627-bd83-5d8a-ae3d-13a22f9d3547', 'D', 'les récepteurs cholinergiques à ce niveau sont de type muscarinique', false, null),
  ('9ab59627-bd83-5d8a-ae3d-13a22f9d3547', 'E', 'toutes ces réponses sont fausses', true, null),
  ('cb7e4675-acd1-5f02-a8f0-f1cc03ecabb5', 'A', 'Comme toutes les cellules vivantes de l''organisme, le neurone est une cellule excitable.', false, null),
  ('cb7e4675-acd1-5f02-a8f0-f1cc03ecabb5', 'B', 'La polarisation membranaire de repos est due à la présence de quelques charges positives en excès à la face externe de la membrane plasmique par rapport à la face interne.', true, null),
  ('cb7e4675-acd1-5f02-a8f0-f1cc03ecabb5', 'C', 'In vitro, un potentiel d''action peut apparaitre au niveau d''une dendrite lorsqu''on lui délivre un stimulus efficace avec un stimulateur électrique.', false, null),
  ('cb7e4675-acd1-5f02-a8f0-f1cc03ecabb5', 'D', 'La vitesse de conduction des potentiels d''action est plus élevée sur un neurone amyélinique que sur un axone myéliniques de petit calibre.', false, null),
  ('ab4d3c58-71c2-58b8-89a1-9d586651b4fe', 'A', 'll est dû au fait que la membrane plasmique du neurone présente une perméabilité sélective aux ions.', true, null),
  ('ab4d3c58-71c2-58b8-89a1-9d586651b4fe', 'B', 'Il s''explique par le faut que les transferts passifs des ions K+ sont plus faciles que ceux des ions Na+.', true, null),
  ('ab4d3c58-71c2-58b8-89a1-9d586651b4fe', 'C', 'Pour que les échanges passifs des ions K+ et Na+ soient réalisables, des mécanismes de transport actifs de ces ions fonctionnent en permanence pour créer et entretenir des gradients de concentration.', true, null),
  ('ab4d3c58-71c2-58b8-89a1-9d586651b4fe', 'D', 'Sa disparition est le signe de la mort du neurone.', true, null),
  ('02db251a-6d8a-52d2-9775-3cab4238b4aa', 'A', 'L''amplitude des potentiels d''action d''un seul et même axone varie en fonction de la tension des stimuli supra liminaires (efficaces).', false, null),
  ('02db251a-6d8a-52d2-9775-3cab4238b4aa', 'B', 'Les fibres afférentes des nerfs peuvent être myélinique et amyéliniques.', true, null),
  ('02db251a-6d8a-52d2-9775-3cab4238b4aa', 'C', 'Les potentiels d''action d''une seule et même cellule nerveuse ont une vitesse de propagation qui diminue au fur et à mesure que l''on s''éloigne du point de stimulation.', false, null),
  ('02db251a-6d8a-52d2-9775-3cab4238b4aa', 'D', 'Les axones des neurones préganglionnaires et des neurones postganglionnaires des voies afférentes du système nerveux végétatifs sont myélinisés.', false, null),
  ('d5c6fa3f-a546-5f0d-a17b-13c8af63d87e', 'A', 'est caractérisé par un excès de charges positives à la face interne de la membrane plasmique.', false, null),
  ('d5c6fa3f-a546-5f0d-a17b-13c8af63d87e', 'B', 'est de l''ordre de 70mV.', false, null),
  ('d5c6fa3f-a546-5f0d-a17b-13c8af63d87e', 'C', 'est maintenu seulement grâce aux pompes Na+ /K+ nécessitant de I''ATP', false, null),
  ('d5c6fa3f-a546-5f0d-a17b-13c8af63d87e', 'D', 'est présent dans toutes les cellules vivantes Anciennes Questions 2010-2022', true, null),
  ('6525b1f5-200b-50af-a326-111b7640d0ea', 'A', 'Réduite de la perméabilité sélective de la membrane neuronale aux ions.', true, null),
  ('6525b1f5-200b-50af-a326-111b7640d0ea', 'B', 'Est maintenu même après la mort de la cellule.', false, null),
  ('6525b1f5-200b-50af-a326-111b7640d0ea', 'C', 'A une valeur fixe et stable à exactement -70 mV chez l''homme.', false, null),
  ('6525b1f5-200b-50af-a326-111b7640d0ea', 'D', 'Son maintien ne nécessite pas de dépense énergétique.', false, null),
  ('6525b1f5-200b-50af-a326-111b7640d0ea', 'E', 'Est spécifique de la cellule nerveuse.', false, null),
  ('ef169d92-b6f2-5ef4-be4d-a292373fca81', 'A', 'La concentration en ions K+ est supérieure en extracellulaire qu’en intracellulaire.', false, null),
  ('ef169d92-b6f2-5ef4-be4d-a292373fca81', 'B', 'La membrane est davantage perméable aux ions K qu’aux ions Na+.', true, null),
  ('ef169d92-b6f2-5ef4-be4d-a292373fca81', 'C', 'Les canaux de fuite K+ engendrent un important flux sortant d’ions K+.', true, null),
  ('ef169d92-b6f2-5ef4-be4d-a292373fca81', 'D', 'Les pompes Na+/K +» assurent le transport d’ions K+ hors de la cellule.', false, null),
  ('ef169d92-b6f2-5ef4-be4d-a292373fca81', 'E', 'Toutes ces réponses sont fausses', false, null),
  ('7713f169-e6c9-550c-a7e6-9fea9204954f', 'A', 'Elle est orthodromique quand l''influx se dirige vers le corps cellulaire', false, null),
  ('7713f169-e6c9-550c-a7e6-9fea9204954f', 'B', 'Elle est orthodromique quand l''influx se dirige vers l''axone', true, null),
  ('7713f169-e6c9-550c-a7e6-9fea9204954f', 'C', 'Elle est antidromique quand l''influx se dirige vers l''axone', false, null),
  ('7713f169-e6c9-550c-a7e6-9fea9204954f', 'D', 'In vivo, elle s''effectue dans le sens antidromique', false, null),
  ('7713f169-e6c9-550c-a7e6-9fea9204954f', 'E', 'Toutes les réponses sont fausses', false, null),
  ('d2e45cd5-184d-5b29-afb1-d9af61f97fdf', 'A', 'est constitué de plusieurs cellules nerveuses.', false, null),
  ('d2e45cd5-184d-5b29-afb1-d9af61f97fdf', 'B', 'peut quelquefois sécréter une hormone qui agira à distance.', true, null),
  ('d2e45cd5-184d-5b29-afb1-d9af61f97fdf', 'C', 'est toujours constitué de trois parties : dendrite, corps cellulaire et cellule de Schwann', false, null),
  ('d2e45cd5-184d-5b29-afb1-d9af61f97fdf', 'D', 'est le seul type de cellule qui a un potentiel de membrane.', false, null),
  ('d2e45cd5-184d-5b29-afb1-d9af61f97fdf', 'E', 'est le seul type de cellule qui est excitable', false, null),
  ('a4c2611b-0ad4-5247-a7b3-3c15ee388ec4', 'A', 'est caractérisé par un excès de charges positives à la face interne de la membrane plasmique', false, null),
  ('a4c2611b-0ad4-5247-a7b3-3c15ee388ec4', 'B', 'est de l''ordre de 70mV', false, null),
  ('a4c2611b-0ad4-5247-a7b3-3c15ee388ec4', 'C', 'est maintenu seulement grâce aux pompes Na+/K+ nécessitant de I''ATP.', false, null),
  ('a4c2611b-0ad4-5247-a7b3-3c15ee388ec4', 'D', 'est maintenu grâce à des canaux potassiques voltage dépendant', false, null),
  ('a4c2611b-0ad4-5247-a7b3-3c15ee388ec4', 'E', 'toutes ces réponses sont fausses', true, null),
  ('e667bd37-1b3b-585c-9def-6a95d9cd35cf', 'A', 'la concentration en ions K+ est supérieure en extracellulaire qu''en intracellulaire', false, null),
  ('e667bd37-1b3b-585c-9def-6a95d9cd35cf', 'B', 'la membrane est d’avantage perméable aux ions K+ qu''aux ions Na+', true, null),
  ('e667bd37-1b3b-585c-9def-6a95d9cd35cf', 'C', 'les canaux de fuite K+ engendrent un important flux sortant d''ions K+', true, null),
  ('e667bd37-1b3b-585c-9def-6a95d9cd35cf', 'D', 'les pompes Na+/K+ assurent le transport d''ions K+ hors de la cellule', false, null),
  ('e667bd37-1b3b-585c-9def-6a95d9cd35cf', 'E', 'toutes ces réponses sont fausses', false, null),
  ('feb75566-083e-577b-8d9b-feb3ca9e0ec9', 'A', 'il est spécifique aux cellules cardiaques', false, null),
  ('feb75566-083e-577b-8d9b-feb3ca9e0ec9', 'B', 'les ions K+ sont les ions les plus représentés à l’extérieur de la cellule', false, null),
  ('feb75566-083e-577b-8d9b-feb3ca9e0ec9', 'C', 'il existe des canaux de fuite pour les ions Na+ maintenant le milieu intracellulaire négatif', false, null),
  ('feb75566-083e-577b-8d9b-feb3ca9e0ec9', 'D', 'Toutes les propositions sont fausses', true, null),
  ('c6de1bc2-e10e-5dbe-a74d-d29bbf163eb2', 'A', 'Seules les cellules musculaires et nerveuses ont une activité électrique membranaire', false, null),
  ('c6de1bc2-e10e-5dbe-a74d-d29bbf163eb2', 'B', 'Toutes les cellules ont le même potentiel de repos', false, null),
  ('c6de1bc2-e10e-5dbe-a74d-d29bbf163eb2', 'C', 'Les dendrites des neurones produisent des potentiels d’action', false, null),
  ('c6de1bc2-e10e-5dbe-a74d-d29bbf163eb2', 'D', 'Toutes les propositions sont fausses', true, null),
  ('4b361bb2-4147-5fdc-be8f-2001073ad9cb', 'A', 'la concentration en ions K+ est supérieure en extracellulaire qu''en intracellulaire.', false, null),
  ('4b361bb2-4147-5fdc-be8f-2001073ad9cb', 'B', 'la membrane est davantage perméable aux ions K+ qu''aux ions Na+', false, null),
  ('4b361bb2-4147-5fdc-be8f-2001073ad9cb', 'C', 'les canaux de fuite K+ engendrent un important flux sortant d''ions K+', false, null),
  ('4b361bb2-4147-5fdc-be8f-2001073ad9cb', 'D', 'les pompes Na+ /K+ assurent le transport d''ions K hors de la cellule', false, null),
  ('1c1bb1a4-c5b6-51c7-918d-780b5b66b430', 'A', 'Catalyse un symport des ions Na'' et K*', false, null),
  ('1c1bb1a4-c5b6-51c7-918d-780b5b66b430', 'B', 'Contribue au potentiel des membranes cellulaires.', true, null),
  ('1c1bb1a4-c5b6-51c7-918d-780b5b66b430', 'C', 'Catalyse un transport ionique électro-neutre.', false, null),
  ('1c1bb1a4-c5b6-51c7-918d-780b5b66b430', 'D', 'Assure I''équilibre osmotique de la cellule.', true, null),
  ('d33381e5-2815-5a11-a765-e2f2ea45369c', 'A', 'Ont une propagation décrémentielle (ex : qui ont une vitesse qui diminue progressivement au fil du temps).', false, null),
  ('d33381e5-2815-5a11-a765-e2f2ea45369c', 'B', 'Ont une amplitude graduable.', false, null),
  ('d33381e5-2815-5a11-a765-e2f2ea45369c', 'C', 'Obéissent à la loi de tout ou rien.', true, null),
  ('d33381e5-2815-5a11-a765-e2f2ea45369c', 'D', 'lls sont sommables.', false, null),
  ('f6616279-117d-5bac-9604-220e7801dd6e', 'A', 'la période réfractaire absolue vient avant la période réfractaire relative.', true, null),
  ('f6616279-117d-5bac-9604-220e7801dd6e', 'B', 'un potentiel d''action peut apparaître lorsque a fibre est en période réfractaire absolue', false, null),
  ('f6616279-117d-5bac-9604-220e7801dd6e', 'C', 'les périodes réfractaires permettent d''augmenter la fréquence de décharge des neurones.', false, null),
  ('f6616279-117d-5bac-9604-220e7801dd6e', 'D', 'en conditions physiologiques, les périodes réfractaires permettent d''orienter le potentiel d''action dans le sens orthodromique', true, null),
  ('c34b44a2-c554-54ae-8a92-48e2282786b3', 'A', 'l''amplitude du potentiel d''action est indépendante du diamètre du neurone.', false, null),
  ('c34b44a2-c554-54ae-8a92-48e2282786b3', 'B', 'le potentiel d''action d''un nerf a une amplitude proportionnelle à l''intensité de la stimulation.', true, null),
  ('c34b44a2-c554-54ae-8a92-48e2282786b3', 'C', 'la vitesse de propagation du potentiel d''action le long d''un neurone est indépendante de l''intensité de stimulation.', true, null),
  ('c34b44a2-c554-54ae-8a92-48e2282786b3', 'D', 'les potentiels post-synaptiques sont toujours des potentiels d''action. Potentiel d’Action', false, null),
  ('0e32de53-3089-55e8-a944-1210d67d1f19', 'A', 'en conditions expérimentales, la conduction peut se faire dans le sens antidromique.', true, null),
  ('0e32de53-3089-55e8-a944-1210d67d1f19', 'B', 'plus l''intensité de la stimulation est grande, plus la vitesse de propagation est élevée.', false, null),
  ('0e32de53-3089-55e8-a944-1210d67d1f19', 'C', 'la fréquence des potentiels d''action est indépendante de l''intensité de la stimulation.', false, null),
  ('0e32de53-3089-55e8-a944-1210d67d1f19', 'D', 'dans un nerf, les fibres sont recrutées par propagation des potentiels d''action aux fibres voisines. Anciennes Questions 2010-2022', false, null),
  ('25315def-5496-537c-ad8c-d8ec6a517441', 'A', 'Répond à la loi de tout ou rien.', true, null),
  ('25315def-5496-537c-ad8c-d8ec6a517441', 'B', 'Ne peut se déclencher que si le potentiel membranaire atteint le seuil critique de-30 mV.', true, null),
  ('25315def-5496-537c-ad8c-d8ec6a517441', 'C', 'Peut se propager dans les deux sens d’un axone, dans les conditions physiologiques.', false, null),
  ('25315def-5496-537c-ad8c-d8ec6a517441', 'D', 'Peut-être excitateur ou inhibiteur.', false, null),
  ('25315def-5496-537c-ad8c-d8ec6a517441', 'E', 'Se propage plus rapidement en l’absence de la cellule de Schwann.', false, null),
  ('98816799-95de-5b7c-88c6-d123ad74566a', 'A', 'Peut-être excitateur quand il résulte de l’ouverture des canaux Cl-', false, null),
  ('98816799-95de-5b7c-88c6-d123ad74566a', 'B', 'N’obéit pas à la loi de tout ou rien.', true, null),
  ('98816799-95de-5b7c-88c6-d123ad74566a', 'C', 'Résulte de l’ouverture de canaux sodiques voltage dépendants.', false, null),
  ('98816799-95de-5b7c-88c6-d123ad74566a', 'D', 'Est limité par une période réfractaire.', false, null),
  ('98816799-95de-5b7c-88c6-d123ad74566a', 'E', 'Peut s’annuler en cas de coexistence de 2 potentiels post-synaptiques de polarité différente.', true, null),
  ('48c2d019-ef85-55d4-8ce1-f62d7e8f5087', 'A', 'La période réfractaire absolue correspond à une durée durant laquelle un potentiel d’action de plus grande amplitude peut exciter la fibre', false, null),
  ('48c2d019-ef85-55d4-8ce1-f62d7e8f5087', 'B', 'La concentration en ions potassium est plus grande dans le milieu extracellulaire que dans la cellule : on parle de gradient électrochimique', false, null),
  ('48c2d019-ef85-55d4-8ce1-f62d7e8f5087', 'C', 'La dépolarisation correspond à une variation du potentiel de la membrane vers des valeurs plus négatives', false, null),
  ('48c2d019-ef85-55d4-8ce1-f62d7e8f5087', 'D', 'Toutes les propositions sont fausses', true, null),
  ('1a571a5e-f6aa-58d5-9dca-b66b27f4cefd', 'A', 'L''entrée de Na+ est inhibée', false, null),
  ('1a571a5e-f6aa-58d5-9dca-b66b27f4cefd', 'B', 'La sortie de K+ est inhibée', false, null),
  ('1a571a5e-f6aa-58d5-9dca-b66b27f4cefd', 'C', 'La sortie de Na+ est inhibée', true, null),
  ('1a571a5e-f6aa-58d5-9dca-b66b27f4cefd', 'D', 'L''entrée de Cl- est inhibée', false, null),
  ('1a571a5e-f6aa-58d5-9dca-b66b27f4cefd', 'E', 'La sortie de Cl- est inhibée', false, null),
  ('e6031d3e-5756-5828-a24e-bfc6b8d6e43d', 'A', 'Existe que dans les cellules excitables', false, null),
  ('e6031d3e-5756-5828-a24e-bfc6b8d6e43d', 'B', 'Traduit un excès de charges positives à l''intérieur de la cellule par rapport à l''extérieur', false, null),
  ('e6031d3e-5756-5828-a24e-bfc6b8d6e43d', 'C', 'Est toujours négative dans toutes les cellules', true, null),
  ('e6031d3e-5756-5828-a24e-bfc6b8d6e43d', 'D', 'Elle devient positive lors de la dépolarisation dans toutes les cellules', false, null),
  ('e6031d3e-5756-5828-a24e-bfc6b8d6e43d', 'E', 'Toutes les réponses sont fausses', false, null),
  ('be2e3039-403c-592c-8a72-d6b4812b57a1', 'A', 'Potentiel seuil-dépolarisation-hyperpolarisation-repolarisation', false, null),
