  ('d4476e0b-458e-5e40-a347-d29164628d0b', 'D', 'Elle diminue avec l''augmentation du diamètre des fibres', false, null),
  ('d4476e0b-458e-5e40-a347-d29164628d0b', 'E', 'Toutes les réponses sont fausses', false, null),
